// district layout across the world (fractions): industrial edges → old town → residential
// → entertainment strips flanking a downtown core in the centre.
function districtAt(x){
  var f=wrapW(x)/WW;
  if(f<0.11||f>=0.89) return DISTRICTS.industrial;
  if(f<0.27||f>=0.78) return DISTRICTS.oldtown;
  if(f<0.42||f>=0.65) return DISTRICTS.residential;
  if(f<0.47||f>=0.60) return DISTRICTS.entertainment;
  return DISTRICTS.downtown;
}
// primary accent/window palette at a world-x (used by the train's district colour stripe)
function zoneAt(wx){ var d=districtAt(wx); return { a:d.pal[0][0], a2:d.pal[0][1], win:d.win }; }
var NEON = ["#ff2a9d","#05d9e8","#2af5b8","#ffb347","#b98cff","#ff5a5a","#5affd7","#ff8cf0"];

// dark facade bases (kept moody; tinted toward the district accent per building)
var BLDBASE = ["#0f0a18","#141020","#1a1430","#0c0a16","#181228","#0a0712","#161022"];

// DAYTIME MATERIAL COLOURS — each building reads as a real material by day (brick / stone / glass /
// concrete / painted), not the old lavender-grey wash. Blended into the facade by DAYLIGHT only, so the
// moody night silhouette is untouched. Restrained + saturated ("high class", ref: distinct material colours).
var DAYMAT = {
  downtown:      [[150,182,176],[164,190,206],[142,160,188],[196,190,168],[176,168,150],[152,172,182]], // green/blue/bronze glass, stone
  oldtown:       [[178,98,74],[190,124,86],[198,170,132],[162,86,68],[152,122,98],[186,146,108]],        // brick red · terracotta · sandstone
  residential:   [[196,176,146],[176,150,120],[198,158,140],[150,166,142],[190,182,162],[178,140,112]],  // brownstone · pastel · sage · tan
  entertainment: [[198,150,120],[184,142,170],[202,178,140],[168,150,192],[196,164,132]],                // warm painted · mauve
  industrial:    [[150,146,140],[170,120,96],[142,140,152],[178,150,120],[132,140,146]]                  // concrete · rust · brick
};
function dayMatFor(dname,seed){ var t=DAYMAT[dname]; if(!t) return null; return t[(seed>>>7)%t.length]; }

// ROOF MATERIALS — so pitched/capped roofs aren't all one slate. New England-appropriate + general:
// slate, copper-green (weathered), red shingle, cedar, tar-black, tin, aged purple-slate. Chosen per
// building by a bseed hash (no r() → determinism-safe). Mixed into the roof mass in drawCrown.
var ROOFMAT = [ [46,50,60],[58,64,76],[150,72,56],[168,92,64],[92,122,104],[74,104,90],
                [98,76,56],[120,90,64],[34,36,44],[120,124,132],[74,60,68],[52,58,66] ];
function roofMatFor(seed){ return ROOFMAT[(seed>>>9)%ROOFMAT.length]; }

// FUNCTIONAL BUILDING TYPE — most buildings are generic office/apartment; a MINORITY are recognizable civic/
// commercial types rendered with a colour/light cue that survives pixel scale (a mid-facade emblem or a lit
// blade sign, NOT fine ground-floor linework the rail/crowds occlude). Derived from district+height+a bseed
// hash — no r(), so the skyline layout is byte-stable. See drawUse().
function useFor(dname,bh,bseed){
  var hh=(bseed>>>17)&255;
  if(dname==="industrial") return hh<120?"factory":(hh<200?"warehouse":"depot");
  if(dname==="downtown")   return hh<11?"hotel":(hh<19?"bank":(hh<26&&bh>=54*KSP?"theater":(hh<33?"store":"office")));
  if(dname==="neon")       return hh<40?"theater":(hh<64?"hotel":(hh<96?"cafe":(hh<112?"store":"office")));   // entertainment strip
  if(dname==="residential")return hh<9?"hospital":(hh<20?"cafe":(hh<30&&bh<40*KSP?"school":(hh<38?"fire":"apartment")));
  if(dname==="oldtown")    return hh<11?"bank":(hh<26?"cafe":(hh<40?"pharmacy":(hh<50?"museum":(hh<58&&bh<40*KSP?"school":"apartment"))));
  return "office";
}

var SKY = { night:[[8,8,26],[16,14,40]], dawn:[[70,40,90],[255,140,90]],
            day:[[92,160,235],[170,215,250]], dusk:[[40,30,80],[255,110,70]] };

// ---- sun (NOAA simplified) ----
function sunTimes(d){
  var rad=Math.PI/180, J1970=2440588, J2000=2451545;
  function toJulian(t){ return t.valueOf()/86400000-0.5+J1970; }
  function fromJulian(j){ return new Date((j+0.5-J1970)*86400000); }
  var n=Math.round(toJulian(d)-J2000-0.0009-(-LON/360));
  var Ja=J2000+0.0009+(-LON/360)+n;
  var M=rad*(357.5291+0.98560028*(Ja-J2000));
  var C=rad*(1.9148*Math.sin(M)+0.02*Math.sin(2*M)+0.0003*Math.sin(3*M));
  var Ls=M+C+rad*102.9372+Math.PI;
  var Jt=Ja+0.0053*Math.sin(M)-0.0069*Math.sin(2*Ls);
  var dec=Math.asin(Math.sin(Ls)*Math.sin(rad*23.4397));
  var cosH=(Math.sin(rad*-0.833)-Math.sin(rad*LAT)*Math.sin(dec))/(Math.cos(rad*LAT)*Math.cos(dec));
  if(cosH>1) return {rise:null,set:null,polar:"night"};
  if(cosH<-1) return {rise:null,set:null,polar:"day"};
  var H0=Math.acos(cosH)/(2*Math.PI);
  return { rise: fromJulian(Jt-H0), set: fromJulian(Jt+H0) };
}
function dayPhase(now){
  var st=sunTimes(now);
  if(st.polar==="night") return {a:"night",b:"night",t:0,light:0};
  if(st.polar==="day") return {a:"day",b:"day",t:0,light:1};
  var t=now.getTime(), r=st.rise.getTime(), s=st.set.getTime(), tw=40*60*1000, k;
  if(t<r-tw||t>s+tw) return {a:"night",b:"night",t:0,light:0};
  if(t<r+tw){ k=(t-(r-tw))/(2*tw); return k<0.5?{a:"night",b:"dawn",t:k*2,light:k}:{a:"dawn",b:"day",t:(k-0.5)*2,light:k}; }
  if(t>s-tw){ k=(t-(s-tw))/(2*tw); return k<0.5?{a:"day",b:"dusk",t:k*2,light:1-k}:{a:"dusk",b:"night",t:(k-0.5)*2,light:1-k}; }
  return {a:"day",b:"day",t:0,light:1};
}

// ---- moon phase (real lunation for the given date) ----
// returns 0=new, 0.25=first quarter, 0.5=full, 0.75=last quarter
function moonPhase(d){
  var JD=d.valueOf()/86400000+2440587.5;             // Unix ms → Julian Date
  var p=(JD-2451550.1)/29.53058867;                  // lunations since a known new moon (2000-01-06)
  p-=Math.floor(p); if(p<0) p+=1;
  return p;
}

// draw the moon at (mx,my) with real illuminated phase mp (0=new,.25=first qtr,.5=full,.75=last qtr)
// the lunar maria (dark "seas"), as fractions of the radius — a fixed pattern so the disc reads as
// unmistakably THE Moon at size, roughly the familiar near-side face.
var MOON_MARIA=[[-0.34,-0.28],[-0.12,-0.44],[0.08,-0.12],[0.30,0.04],[0.04,0.30],[-0.26,0.36],[0.40,-0.26],[-0.44,0.06]];
// The Moon at (mx,my), real illuminated phase mp (0=new .5=full). R=radius px. dayFade 0..1:
// 0 = night (bright disc + halo + colony), 1 = daytime (a pale wash hanging in the blue). blood=eclipse.
function drawMoon(g,mx,my,mp,colony,R,dayFade,portent,now){
  R=R||6; dayFade=dayFade||0; portent=portent||0; now=now||0; var night=1-dayFade, day=dayFade>0.35;
  var ca=Math.cos(2*Math.PI*mp), wax=mp<0.5, illum=(1-ca)/2, blood=eclipseMoon;
  if(!day){ g.globalCompositeOperation="lighter";                                     // soft halo — night only
    g.fillStyle=(blood?"rgba(200,60,40,":"rgba(220,226,240,")+((0.05+0.14*illum)*night).toFixed(3)+")";
    g.fillRect((mx-R-3)|0,(my-R-3)|0,2*R+7,2*R+7); g.globalCompositeOperation="source-over"; }
  var litA=(0.42+0.30*night).toFixed(2), darkA=(0.10*night).toFixed(2);
  for(var dy=-R;dy<=R;dy++){ var mw=Math.sqrt(R*R-dy*dy);
    for(var dx=-R;dx<=R;dx++){ if(dx*dx+dy*dy>R*R+0.7) continue;
      var xt=ca*mw, mlit=blood?true:(wax?(dx>=xt-0.001):(dx<=-xt+0.001));              // phase terminator
      if(mlit) g.fillStyle=blood?"#b83c28":(day?"rgba(240,242,250,"+litA+")":"#eef0e6");
      else     g.fillStyle=blood?"#7a2818":(day?"rgba(214,222,236,"+darkA+")":"rgba(150,158,178,0.16)");
      // PARTIAL LUNAR ECLIPSE: Earth's shadow eats the disc from one limb. Honest by design — a 40%
      // partial is a bite out of a white Moon, not a blood moon, and that is what you would see.
      if(!blood && eclipseMoonBite>0){ var shEdge=R-2*R*eclipseMoonBite;
        if(dx<=shEdge) g.fillStyle=day?"rgba(150,120,120,"+darkA+")":"rgba(96,44,36,0.85)"; }
      g.fillRect((mx+dx)|0,(my+dy)|0,1,1); } }
  if(!blood){ for(var s=0;s<MOON_MARIA.length;s++){ var px=Math.round(MOON_MARIA[s][0]*R), py=Math.round(MOON_MARIA[s][1]*R);
    if(px*px+py*py>R*R-1.5) continue; var xt3=ca*Math.sqrt(Math.max(0,R*R-py*py)), onLit=wax?(px>=xt3):(px<=-xt3);
    if(!onLit) continue;                                                               // maria only show on the lit face
    g.fillStyle=day?"rgba(200,208,224,"+(0.55*night).toFixed(2)+")":"rgba(120,128,150,0.5)";
    g.fillRect((mx+px)|0,(my+py)|0,1,1); if(R>=6) g.fillRect((mx+px+(wax?-1:1))|0,(my+py)|0,1,1); } }   // the seas
  // THE LUNAR CITY — humanity's settlement grows on the near face over the eons: a lamp, a cluster,
  // then a glittering city with dome-glow and a lit skyline on the limb. Fixed layout (same city each night).
  if((colony||0)>0.08 && !blood && !day){
    var lvl=Math.min(1.3,colony), cnt=Math.min(11,1+Math.floor(lvl*11)), lr=rng(0x4C554E41);   // "LUNA" — deterministic city
    g.globalCompositeOperation="lighter";
    for(var ci=0;ci<cnt;ci++){ var la=lr()*6.283, lrad=Math.sqrt(lr())*R*0.86, cxp=Math.round(Math.cos(la)*lrad), cyp=Math.round(Math.sin(la)*lrad*0.9);
      if(cxp*cxp+cyp*cyp>R*R-1){ lr(); continue; }
      var lxt=ca*Math.sqrt(Math.max(0,R*R-cyp*cyp)), onDark=wax?(cxp<lxt):(cxp>-lxt);   // city lights cover the near side; they BLAZE on the earthshine-dark part
      g.fillStyle=(lr()<0.28?"rgba(255,236,182,":"rgba(160,240,255,")+(onDark?0.95:0.55)+")"; g.fillRect((mx+cxp)|0,(my+cyp)|0,1,1); }
    var sideC=wax?-1:1;
    if(lvl>0.30){ g.fillStyle="rgba(130,224,255,"+(0.16+0.32*lvl).toFixed(2)+")"; g.fillRect((mx+Math.round(sideC*R*0.3)-1)|0,(my-1)|0,4,3);   // the great dome's glow
      g.fillStyle="rgba(150,232,255,"+(0.10*lvl).toFixed(2)+")"; g.fillRect((mx-R)|0,(my-R)|0,2*R+1,2*R+1); }                                    // a faint colony-glow over the whole disc
    if(lvl>0.65){ g.fillStyle="rgba(170,236,255,"+(0.22*(lvl-0.65)/0.65).toFixed(2)+")"; g.fillRect((mx-R+1)|0,(my+R-3)|0,2*R-2,3); }             // a lit lunar skyline on the limb
    g.globalCompositeOperation="source-over";
  }
  // BLOOD PORTENT — as the apocalypse nears the Moon reddens and pulses (it already loomed larger via R)
  if(portent>0 && !blood && !day){ g.globalCompositeOperation="lighter"; var pp=0.68+0.32*Math.sin(now*0.006);
    g.fillStyle="rgba(212,52,30,"+(0.42*portent*pp).toFixed(3)+")"; fillEllipse(g,mx,my,R,R);
    g.fillStyle="rgba(200,40,24,"+(0.14*portent).toFixed(3)+")"; fillEllipse(g,mx,my,R+3,R+3);        // a bloody halo
    g.globalCompositeOperation="source-over"; }
}
// SHATTERED — the black hole tears the Moon into a drifting ring of rubble
function drawMoonDebris(g,mx,my,R,shatter,now){
  var dr=rng(0x44454252), spread=1+shatter*1.6;
  g.globalCompositeOperation="lighter"; g.fillStyle="rgba(180,150,140,0.10)"; fillEllipse(g,mx,my,R*spread*1.3,R*spread*0.7); g.globalCompositeOperation="source-over";  // dust ring
  for(var c=0;c<12;c++){ var a=dr()*6.283, rad=(0.25+dr()*0.85)*R*spread, cx=mx+Math.cos(a)*rad, cy=my+Math.sin(a)*rad*0.8, cs=Math.max(1,R*(0.11+dr()*0.15));
    g.fillStyle="rgb(150,146,150)"; fillEllipse(g,cx,cy,cs,cs*0.82);
    g.fillStyle="rgba(80,78,88,0.7)"; fillEllipse(g,cx+cs*0.3,cy+cs*0.25,cs*0.5,cs*0.4);              // shard shadow
    if(dr()<0.5){ g.globalCompositeOperation="lighter"; g.fillStyle="rgba(255,120,50,"+(0.55*shatter)+")"; g.fillRect(cx|0,cy|0,1,1); g.globalCompositeOperation="source-over"; } }  // molten crack
}
// LUNAR COLONY FALLS — war reaches the Moon: surface explosions flash and evacuation ships flee
function drawColonyFall(g,mx,my,R,cf,now){
  g.globalCompositeOperation="lighter";
  for(var e=0;e<3;e++){ var ph=((now+e*700)%1400)/1400, ex=mx+((e*97)%7-3)*R*0.18, ey=my+((e*53)%5-2)*R*0.18;
    if(ph<0.4){ var f=1-ph/0.4; g.fillStyle="rgba(255,150,60,"+(0.8*f*cf).toFixed(2)+")"; fillEllipse(g,ex,ey,R*0.22*(1+ph),R*0.22*(1+ph)); } }   // explosions on the surface
  for(var s=0;s<2;s++){ var sp=((now+s*900)%2600)/2600, sd=s?1:-1, sx=mx+sd*sp*R*3, sy=my-sp*R*1.4;   // ships fleeing the Moon
    g.fillStyle="rgba(232,242,255,"+(0.85*(1-sp)*cf).toFixed(2)+")"; g.fillRect(sx|0,sy|0,1,1);
    g.fillStyle="rgba(255,200,120,"+(0.5*(1-sp)*cf).toFixed(2)+")"; g.fillRect((sx-sd)|0,sy|0,1,1); }
  g.globalCompositeOperation="source-over";
}
// during a (non-moonfall) apocalypse the Moon reacts ON TOP of the doom sky: blood-red loom (portent),
// the black hole shatters it to a debris ring, or war fells the lunar colony. Only while it's up.
function drawApocMoon(g,now,nd,L){
  if(cityPhase!=="apoc"||curDeath==="moonfall") return; var fx=wfx(); if(fx.rain||fx.snow||fx.fog||fx.thunder) return;
  var lst=lstHours(nd), mrd=moonRaDec(nd), maa=altAz(mrd.ra,mrd.dec,lst); if(maa.alt<2) return;
  refreshMoonEclipse(nd); var mp=moonPhase(nd);
  var portent=Math.min(1,cityApoc*1.15), shatter=(curDeath==="bh")?Math.max(0,Math.min(1,(cityApoc-0.25)/0.5)):0;
  var mcol=colonyLevel('moon',now), colFall=(curWar&&curWar.f>=0&&curWar.f<1.4&&mcol>0.12)?Math.min(1,curWar.f):0;
  var colonyArg=colFall>0?mcol*(1-colFall*0.75):(portent>0.3?mcol*(1-portent):mcol);
  var R=Math.round(9+portent*5), mwx=skyWX(maa.az), mwy=skyY(maa.alt)*0.96;   // BIGGER moon (Nick 2026-07-18)
  for(var w=-1;w<=1;w++){ var mx=mwx-WOFF+w*WW; if(mx<-R-10||mx>SW+R+10) continue;
    if(shatter>0.5) drawMoonDebris(g,mx,mwy,R,shatter,now);
    else { drawMoon(g,mx,mwy,mp,colonyArg,R,0,portent,now); if(colFall>0) drawColonyFall(g,mx,mwy,R,colFall,now); } }
}

