  var ex=MW_M[0][0]*gx+MW_M[1][0]*gy+MW_M[2][0]*gz,
      ey=MW_M[0][1]*gx+MW_M[1][1]*gy+MW_M[2][1]*gz,
      ez=MW_M[0][2]*gx+MW_M[1][2]*gy+MW_M[2][2]*gz;
