function disWarnLine(di){
  return DIS_WARN_LINE[di.type] || ("EMERGENCY WARNING - "+(DIS_NAME[di.type]||"INCIDENT")+" IMMINENT");
}
// ⚠ AND THE RECOVERY LINE REPORTS WHAT IS ACTUALLY HAPPENING, not a countdown. It reads the phase and
// the category off the live descriptor, so it can never claim a recovery that is not being drawn.
function disRecoverLine(arc){
  var n=DIS_NAME[arc.di.type]||"THE INCIDENT", cat="CAT-"+arc.di.intensity;
  if(arc.phase==="ripple")
    return arc.di.win ? ("THE "+n+" HAS PASSED - CASUALTIES BEING COUNTED")
                      : ("THE "+n+" HAS PASSED - "+cat+" DAMAGE, DISTRICTS UNREACHABLE");
  if(arc.f<0.45) return "RECOVERY UNDERWAY - CREWS AND MEDICS WORKING THE "+n+" ZONE";
  if(arc.f<0.80) return "CLEARANCE CONTINUES - POWER AND WATER RETURNING BLOCK BY BLOCK";
  return arc.di.ruin ? ("THE "+n+" ZONE WILL NOT BE REBUILT THIS GENERATION")
                     : ("REBUILDING AFTER THE "+n+" - SCAFFOLDING UP ACROSS THE DISTRICT");
}
function tickerMsg(now){
  var mn=meteorNews(now); if(mn) return mn;                     // the incoming planet-killer dominates the news for ~2 days out
  if(cityPhase==="apoc") return "EMERGENCY BROADCAST - EVACUATE "+cityName+" NOW";
  // ---- THE CHRONICLE REMEMBERS WHO, NOT JUST WHAT. Locked answer 7: recorded everywhere — the live
  // ticker, the almanac and the HUD. This function IS the chronicle's source (it is what gets written
  // into chronicles/life-N.md), and every entry it produced for a disaster read "BREAKING - CAT-5
  // KAIJU - SEEK SHELTER". A life's history was a list of weather warnings with nobody in it.
  // A dead mayor outranks the event that killed them, and a named citizen outranks the category.
  if(curMayor&&curMayor.emergency&&curMayor.deadName&&(Math.floor(now/9000))%3===0)
    return "MAYOR "+curMayor.deadName+" IS DEAD - "+curMayor.winName+" SWORN IN";
  if(curDis){
    var nrc=namedDeadRevealed(curDis);
    if(nrc>0&&(Math.floor(now/9000))%2===0){
      var dc=namedDeadAt(curDis,(Math.floor(now/9000))%nrc);
      if(dc&&!dc.mayor)
        return "NAMED AMONG THE DEAD - "+dc.name+", "+dc.role+" - "+DIS_NAME[curDis.type];
    }
  }
  // ---- THE ARC, NARRATED. 🔒 "the ticker narrates the whole arc from warning through recovery" — and
  // it reads from real state, never a fabricated string: the phase, the category and the type all come
  // off the same descriptor the renderer is drawing from.
  // ⚠ The WARNING outranks an ordinary in-progress disaster (people need telling before it lands) but
  // stays below an invasion and below the named dead, which are already ranked above this line.
  if(curDisArc&&curDisArc.phase==="warn"&&!curDis)
    return disWarnLine(curDisArc.di);
  if(curWar&&curWar.f>=0&&curWar.f<1) return "INVASION UNDERWAY - SHELTER IN PLACE";
  if(curWar&&curWar.f>=1&&!curWar.win) return "CURFEW IN EFFECT BY ORDER OF THE OCCUPATION";
  if(curDis) return "BREAKING - CAT-"+curDis.intensity+" "+DIS_NAME[curDis.type]+(curDis.type==="rift"?" - "+riftInvaderNames(curDis)+" SIGHTED":"")+" - SEEK SHELTER";
  // …and the aftermath, once the impact is over and the crews are out
  if(curDisArc&&!curDis&&(curDisArc.phase==="ripple"||curDisArc.phase==="recover"))
    return disRecoverLine(curDisArc);
  if(curBills) return billsTicker(now);   // gameday takes over the news entirely — every ticker + news screen goes Bills (real safety broadcasts above still win)
  var rgm=regimeTicker(now); if(rgm && (Math.floor(now/12000))%4!==0) return rgm;   // THE ORDER dominates the news (3 of 4 slots) while the takeover is underway
  var pgm=plagueTicker(now); if(pgm && (Math.floor(now/12000))%4!==0) return pgm;   // THE PLAGUE dominates the news while the pandemic rages (mutually exclusive with the regime)
  var ftm=festivalTicker(now); if(ftm && (Math.floor(now/12000))%4!==0) return ftm;  // THE FESTIVAL's expo news while the World's Fair is on (mutually exclusive with war/regime/plague)
  var adm=addictionTicker(now); if(adm && (Math.floor(now/12000))%4!==0) return adm;  // THE ADDICTION CRISIS dominates the news while it rages (mutually exclusive with the others)
  var ttk=titanTicker(now); if(ttk) return ttk;   // the treeline outranks weather but never a real emergency
  // ---- THE TAKEOVER, IN THE CITY'S OWN WORDS. 🔒 Nick's pick: CIVIC LANGUAGE — they cannot name it.
  // A city with a monorail and a casino, sitting under an ancient kingdom, meeting a mythic thing and
  // reaching for the vocabulary of a weather advisory. That gap is the joke and the dread at once, and
  // it is what makes the two halves of this land read as ONE world rather than two pictures.
  // ⚠ Ranked below every real emergency above — a CAT-5 outranks a shadow — and it takes three ticker
  // slots in four, like the regime, so ordinary city news still gets through.
  var gtk=ganonTicker(now); if(gtk && (Math.floor(now/12000))%4!==0) return gtk;
  var fx=wfx();
  if(fireBurning) return "WILDFIRE ON THE RIDGE - STAY CLEAR OF THE TREELINE";
  if(iceNow) return "THE BAY IS FROZEN - SKATE AT YOUR OWN JOY";
  // ⚠ THE SURGE ANNOUNCES ITSELF BEFORE IT ARRIVES — locked answer 25, "sirens and the ticker warn first",
  // wired to the same machinery the eruption's warning uses rather than a second notification system.
  if(curBiome.k==="sprawl"&&hasOcean&&seaW>0){
    var sgT=sprawlSurgeState(now);
    if(sgT.s>0.30) return "STORM SURGE - THE FLATS ARE UNDER WATER, AVOID THE WATERFRONT";
    if(sgT.s>0.10) return "SURGE WARNING - HIGH WATER EXPECTED ON THE FLATS";
    if(sgT.mark>0.25&&sgT.s<0.08) return "SURGE RECEDING - CREWS CLEARING THE WATERFRONT";
  }
  if(curBlk) return curBlk.fix?"CREWS RESTORING POWER - GRID BACK SHORTLY":"STORM BLACKOUT DOWNTOWN - CREWS EN ROUTE";
  if(curOutbreak) return curOutbreak.f<0.7?"HEALTH ADVISORY - MASKS RECOMMENDED CITYWIDE":"OUTBREAK WANES - HOSPITALS REPORT RECOVERY";
  if(fx.thunder) return "SEVERE THUNDERSTORM WARNING FOR "+cityName;
  if(fx.snow) return "WINTER STORM - PLOWS DEPLOYED CITYWIDE";
  if(fx.rain||fx.drizzle) return "RAIN CONTINUES - "+Math.round(weather.temp==null?60:weather.temp)+"F DOWNTOWN";
  if(fx.fog) return "DENSE FOG ADVISORY - LOW VISIBILITY DOWNTOWN";
  if(fx.cloudy) return ((weather.cloud||0)>=88?"OVERCAST":"CLOUDY")+" SKIES OVER "+cityName+" - "+Math.round(weather.temp==null?60:weather.temp)+"F";
  if(airshowState(now)) return "AIRSHOW OVER "+cityName+" - LOOK UP";
  if(curEvents&&curEvents.parade) return "PARADE TODAY ON MAIN STREET";
  if(curEvents&&curEvents.champ) return cityName+" "+teamName+" WIN THE TITLE - PARADE DOWNTOWN";
  if(curEvents&&curEvents.market) return "FARMERS MARKET OPEN UNTIL 4 PM";
  if(curEvents&&curEvents.foodfest) return "STREET FOOD FESTIVAL ON MARKET ROW - COME HUNGRY";
  if(curEvents&&curEvents.concert) return "LIVE MUSIC TONIGHT AT THE FAIRGROUND STAGE";
  if(curEvents&&curEvents.icerink) return "THE PLAZA ICE RINK IS OPEN - SKATES FOR RENT";
  if(curEvents&&curEvents.movie) return "MOVIE NIGHT IN THE PLAZA AT DUSK";
  if(curSpace>0.3) return cityName+" SPACEPORT - NEXT LAUNCH BOARDING";
  var nd2=nowDate(), gm=gameNight(nd2);
  var shw=currentShower(nd2); if(shw && (Math.floor(now/8000))%4===0) return shw.n+" METEOR SHOWER PEAKS TONIGHT - LOOK UP";   // announce the real shower so nobody misses it
  var adm=astroDesk(nd2); if(adm && (Math.floor(now/8000))%4===1) return adm;   // the astronomy desk: eclipses (with the time), supermoons, conjunctions, comet season, advance notices
  if(dimDuoNow(now)) return "STRANGE VISITORS FROM ANOTHER DIMENSION SPOTTED DOWNTOWN";
  var issp=issAltAzNow(now); if(issp && issp.alt>12 && dayPhase(nd2).light<0.30) return "THE ISS IS PASSING OVERHEAD NOW - LOOK UP";   // a real overhead pass is a brief, unmissable event
  var msgs=["WELCOME TO "+cityName,"POP "+popFmt(cityPop())+" AND GROWING",cityName+" TRANSIT - ALL LINES RUNNING"];
  var appr=approvalNow(now);   // N3 (shared with the civic HUD)
  msgs.push("CITY APPROVAL "+appr+" PCT");
  msgs.push(curEcon>0.5?("BUDGET SURPLUS "+(1+Math.round(curEcon*6))+"M"):("BUDGET DEFICIT "+(1+Math.round((1-curEcon)*5))+"M"));
  if(curCruise&&curCruise.f>0.2&&curCruise.f<0.82) msgs.push("CRUISE SHIP IN PORT - WELCOME VISITORS");
  var FI=famInfo(now), cg3=cityGrowth(now);                                                   // N4+: the generations
  var FMS=[[0.30,"WEDDING BELLS - "+FI.pA+" AND "+FI.pB+" "+FI.sur],
    [FI.k1.born,"THE "+FI.sur+" FAMILY WELCOMES LITTLE "+FI.k1.name]];
  if(FI.k2) FMS.push([FI.k2.born,"A SECOND CHILD FOR THE "+FI.sur+"S - WELCOME "+FI.k2.name]);
  FMS.push([0.50,FI.k1.name+" "+FI.sur+" - FIRST DAY OF SCHOOL"],
    [0.55,FI.k1.name+" "+FI.sur+" CHOOSES A CALLING - "+JOBS[FI.k1.job][0]],
    [FI.wed,FI.k1.name+" "+FI.sur+" MARRIES IN THE PLAZA TODAY"],
    [FI.g3.born,"A GRANDCHILD FOR "+FI.pA+" AND "+FI.pB+" "+FI.sur],
    [0.70,FI.sur.toUpperCase()+" AND "+(FI.k1.name)+" OPEN \""+FI.sur+" AND "+(FI.k2?"FAMILY":"SON")+"\" ON MARKET ROW"],
    [0.74,"TWO HOUSES JOINED - A "+FI.sur+" WEDS A "+LNAMES[(FI.sur.length*7+3)%LNAMES.length]],
    [0.78,FI.k1.name+" THE "+JOBS[FI.k1.job][0]+" NAMED CITIZEN OF THE YEAR"],
    [0.82,"THE "+FI.sur+" HEIRLOOM TURNS 100 - STILL ON THE SILL"],
    [FI.elder,"THE CITY HONORS ELDER "+FI.pA+" "+FI.sur+" - FLAGS AT HALF MAST"]);
  for(var fm2=0;fm2<FMS.length;fm2++) if(Math.abs(cg3.cy-FMS[fm2][0])<0.006) return FMS[fm2][1];
  var CM=citizenMilestones(now); for(var cm2=0;cm2<CM.length;cm2++) if(Math.abs(cg3.cy-CM[cm2][0])<0.006) return CM[cm2][1];   // civic-cast turning points BREAK IN (like the family milestones)
  if(gm) msgs.push("GAME NIGHT - "+cityName+" "+teamName+" AT 7","GO "+teamName+"!");
  if(curMayor&&curMayor.campaign){ msgs.push("ELECTION AHEAD - "+curMayor.winName+" VS "+curMayor.loseName,"RALLY TONIGHT IN THE PLAZA");
    var nm5=curMayor.nextMeasures; if(nm5&&nm5.length) msgs.push("ON THE BALLOT - PROP "+MEASURE_LABEL[nm5[0].t]+(nm5[1]?(" AND "+MEASURE_LABEL[nm5[1].t]):"")); }
  if(curMayor&&curMayor.electionDay) msgs.push("POLLS OPEN - VOTE TODAY");
  // the succession. The ticker returns to the dead by NAME (locked answer 17) rather than reporting a
  // vacancy as an administrative fact.
  if(curMayor&&curMayor.emergency){
    msgs.push("CITY HALL IN MOURNING - MAYOR "+curMayor.deadName+" IS DEAD",
              "EMERGENCY SUCCESSION - "+curMayor.winName+" SWORN IN",
              "FLAGS AT HALF MAST ACROSS "+cityName,
              "THE CITY REMEMBERS MAYOR "+curMayor.deadName);
  }
  // ---- THE TICKER RETURNS TO THEM BY NAME. Locked answer 17. Only the mayor got a tribute before,
  // which made everyone else a number that scrolled past once. These are the people the panel named
  // while they were being counted; the ticker is where the city says their names afterwards.
  if(curDis){
    var nr2=namedDeadRevealed(curDis);
    for(var td=0;td<nr2&&td<3;td++){
      var dd2=namedDeadAt(curDis,td); if(!dd2||dd2.mayor) continue;
      msgs.push(dd2.name+" - "+dd2.role+" - REMEMBERED BY "+cityName,
                "TRIBUTES FOR "+dd2.name+" AT THE SITE");
    }
  }
  if(curMayor&&curMayor.justElected){ msgs.push("MAYOR "+curMayor.winName+" TAKES OFFICE - "+curMayor.party.k+" AGENDA");
    var jm5=curMayor.measures||[]; for(var mi5=0;mi5<jm5.length;mi5++){ var mm5=jm5[mi5];
      msgs.push("PROP "+MEASURE_LABEL[mm5.t]+" - "+(mm5.pass?"PASSES ":"FAILS ")+mm5.yes+"-"+(100-mm5.yes)); } }
  if(curMayor&&curMayor.debate) msgs.push("MAYORAL DEBATE TONIGHT - "+curMayor.winName+" VS "+curMayor.loseName);
  if(curMayor&&curMayor.campaign) msgs.push("LATEST POLL - "+curMayor.winName+" LEADS "+curMayor.loseName);
  if(curMayor&&curMayor.justElected) msgs.push(curMayor.share>=58?("LANDSLIDE WIN FOR "+curMayor.winName):curMayor.share<=53?("RAZOR-THIN - RECOUNT CONFIRMS "+curMayor.winName):curMayor.hold?(curMayor.party.k+" HOLDS CITY HALL"):(curMayor.winName+" ELECTED MAYOR"));
  if(curMayor&&curMayor.scandal) msgs.push(curMayor.ousted?("MAYOR OUSTED - "+curMayor.winName+" SWORN IN"):(curMayor.recallVote?"RECALL VOTE UNDERWAY AT CITY HALL":"CITY HALL ROCKED BY SCANDAL"));
  if(curEcon>0.65) msgs.push("MARKETS RALLY - CRANES OVER "+cityName);
  if(curEcon<0.35) msgs.push("MARKETS SLUMP - STOREFRONTS GO DARK");
  if(curSlump>0.55) msgs.push("HOMELESS CRISIS DEEPENS - TENT CITIES SPREAD DOWNTOWN");   // v1.41 hard times on the ticker
  else if(curSlump>0.2 && curSlump<=0.55) msgs.push("SHELTERS REPORT FEWER IN NEED AS THE ECONOMY STEADIES");   // recovery beat
  if(curSlump>0.25 && curMayor && (curMayor.party.k==="GREENS"||curMayor.party.k==="TRANSIT")) msgs.push("MAYOR "+curMayor.winName+" OPENS A NEW SHELTER AND SOUP KITCHEN");
  if(curSlump>0.25 && curMayor && curMayor.party.k==="SAFETY") msgs.push("CITY CLEARS DOWNTOWN ENCAMPMENTS - ADVOCATES PROTEST");
  if(cityHasBuild("casino")){ msgs.push("CASINO ZONE DRAWS RECORD CROWDS - TOURISM UP"); msgs.push("POLICE ADD PATROLS AROUND THE CASINO DISTRICT"); }
  if(curPolicies.heightcap&&curEcon<0.45) msgs.push("DEVELOPERS BLAME HEIGHT CAP FOR STALLED GROWTH");
  if(cityHasBuild("park")) msgs.push("CITY PARK NAMED BEST NEW PUBLIC SPACE");
  // ---- CIVIC LANDMARK headlines: a GRAND OPENING beat preempts the ticker; once built, ambient civic-pride/tourism news ----
  var isJune=(nowDate().getMonth()===5);
  for(var lb=0;lb<curBuilds.length;lb++){ var lcb=curBuilds[lb]; if(!lcb.civic) continue;
    var open=(lcb.bp==="open"), lname=CIVIC_LABEL[lcb.t];
    if(lcb.t==="university"){ if(open) return "THE NEW UNIVERSITY OPENS - FIRST CLASS ENROLLS"; msgs.push(isJune?"GRADUATION DAY - CAPS FLY AT THE UNIVERSITY":("UNIVERSITY RESEARCH PUTS "+cityName+" ON THE MAP")); }
    else if(lcb.t==="grandcentral"){ if(open) return "GRAND CENTRAL TERMINAL OPENS - THE TRAINS ROLL IN"; msgs.push("GRAND CENTRAL BUSTLES - RECORD RIDERSHIP DOWNTOWN"); }
    else if(lcb.t==="zoo"){ if(open) return "THE CITY ZOO OPENS ITS GATES TODAY"; msgs.push("CITY ZOO WELCOMES A NEW ARRIVAL - TOURISM UP"); }
    else if(lcb.t==="marina"){ if(open) return "THE NEW MARINA OPENS - SAILS FILL THE BAY"; msgs.push("MARINA DRAWS YACHTS AND VISITORS - TOURISM UP"); }
    else if(lcb.t==="observatory"){ if(open) return "THE OBSERVATORY OPENS - PUBLIC STARGAZING NIGHTS"; msgs.push("OBSERVATORY TRACKS A COMET OVER "+cityName); } }
  var bn=corpNews(now); for(var ci2=0;ci2<bn.length;ci2++) msgs.push(bn[ci2]);   // corporate business headlines (rise/IPO/merger/bankruptcy)
  var slot=Math.floor(now/12000);
  var cb=citizenBeat(now);   // the featured citizen's current status gets EVERY 3RD slot — steady, followable airtime for a story arc
  if(cb && slot%3===0) return cb;
  return msgs[slot%msgs.length];
}
// ---- NEWSPAPERS: when something big happens, papers spread the word — extras blow across the
//      city on the wind, tumbling out from wherever the event is. (The words themselves scroll on
//      the LED ticker; these are the papers physically spreading the news.) ----
// (newsEvent / drawNewspaper / drawNewsFlurry removed 2026-07-12 — user found the sky papers
//  weird and hard to read; major events are still narrated on the LED ticker below.)
function drawTicker(g,L,now,night){
  if(cityG<0.55) return;
  var wx=Math.round(0.47*WW), bw=46, y=HORIZON-52;
  for(var w=-1;w<=1;w++){ var X=(wx-WOFF+w*WW)|0; if(X+bw<-4||X>SW+4) continue;
    g.fillStyle=L>0.5?"#3a3f4a":"#141821"; g.fillRect(X,y+7,2,HORIZON-y-7); g.fillRect(X+bw-2,y+7,2,HORIZON-y-7);
    g.fillStyle=L>0.5?"#23262e":"#0a0b10"; g.fillRect(X-1,y-1,bw+2,9);
    g.save(); g.beginPath(); g.rect(X,y,bw,7); g.clip();
    var msg=tickerMsg(now), tw2=(msg.length*4-1)+30, off=(now*0.014)%tw2;
    drawUiText(g,msg,(X+bw-off)|0,y+1,night>0.5?"#ffb347":"#e8862a",1);
    drawUiText(g,msg,(X+bw-off+tw2)|0,y+1,night>0.5?"#ffb347":"#e8862a",1);
    g.restore();
    if(night>0.4){ g.globalCompositeOperation="lighter"; g.fillStyle="rgba(255,160,60,0.10)";
      g.fillRect(X,y,bw,7); g.globalCompositeOperation="source-over"; }
  }
}
// is anything news-worthy happening right now? (cuts the building screens to red BREAKING coverage)
function newsEmergency(){
  return cityPhase==="apoc" || !!curDis || (curWar&&curWar.f>=0&&curWar.f<1) || !!curBlk || !!curOutbreak || fireBurning;
}
// big LED NEWS SCREENS mounted high on the downtown towers — they run the LOCAL city news, and cut to
// red BREAKING coverage the instant anything happens (disaster, invasion, the incoming meteor…), so the
// story is visible right on the skyline. Each screen dies with its tower when the cataclysm reaches it.
// v1.24 STATE MEDIA — under THE ORDER the jumbotrons stop showing news and show the leader's portrait
// + a rotating slogan (propaganda faces). A small stern pixel portrait: crimson cap w/ emblem, hard eyes.
function drawStateScreen(g,sx,sy,sw,sh,now,L){
  g.fillStyle="#5a1418"; g.fillRect(sx-1,sy-1,sw+2,sh+2);                               // crimson bezel
  g.fillStyle="#1a0407"; g.fillRect(sx,sy,sw,sh);                                       // dark screen
  g.fillStyle="#7a1018"; g.fillRect(sx,sy,sw,4);                                        // header bar
  drawUiText(g,"STATE",sx+1,sy,"#ffd2c4",1);
  if((Math.floor(now/500))&1){ g.fillStyle="#ff3b3b"; g.fillRect(sx+sw-3,sy+1,2,2); }   // blinking LIVE dot
  var px=sx+3, py=sy+5;                                                                 // the leader's portrait (left)
  g.fillStyle="#d8b48c"; g.fillRect(px,py+2,5,5);                                       // face
  g.fillStyle="#c39a72"; g.fillRect(px,py+2,1,5);                                       // cheek shade
  g.fillStyle="#8a1018"; g.fillRect(px-1,py,7,2); g.fillRect(px-1,py+1,1,1); g.fillRect(px+5,py+1,1,1);   // crimson cap
  g.fillStyle="#f4eee2"; g.fillRect(px+2,py,1,1);                                       // cap emblem
  g.fillStyle="#241610"; g.fillRect(px+1,py+4,1,1); g.fillRect(px+3,py+4,1,1);          // hard eyes
  g.fillStyle="#3a2a1e"; g.fillRect(px+1,py+3,4,1);                                     // stern brow
  g.fillStyle="#7a1018"; g.fillRect(px,py+7,5,1);                                       // collar
  var sl=ORDER_SLOGANS[(Math.floor(now/2600))%ORDER_SLOGANS.length];                    // rotating slogan (right)
  drawUiText(g,sl.substr(0,Math.max(1,((sw-11)/4)|0)),px+8,sy+7,"#ffe0d0",1);
  g.globalCompositeOperation="lighter"; g.fillStyle="rgba(220,40,40,"+(0.10+0.10*(1-L)).toFixed(2)+")"; g.fillRect(sx,sy,sw,sh); g.globalCompositeOperation="source-over";   // screen glow
}
function drawNewsScreens(g,L,now,night){
  if(curNoAds) return;      // no building-scale LED news screens (village ban + the ancient kingdom)

  if(cityG<0.5) return;
  var msg=tickerMsg(now), emerg=newsEmergency();
  var parts=cityName.split(" "), tag=""; for(var pi=0;pi<parts.length&&pi<3;pi++) tag+=parts[pi].charAt(0);
  var hdr=emerg?"BREAKING":(tag+" NEWS");
  var drawn=0;
  for(var i=0;i<near.blds.length && drawn<5;i++){ var b=near.blds[i];
    if(b.type==="park"||b.h<46||b.w<14) continue;                          // tall, wide-enough downtown towers only
    if(((b.seed>>>4)%4)!==0) continue;                                      // only some towers carry a big screen
    if(b.bAge!==undefined && cityG-b.bAge<=bandOf(b)) continue;             // not before the tower is built
    if(overLandmark(b.x,b.w)) continue;
    if(apocHit(b.x)) continue;                                             // the screen is gone once the tower is destroyed
    var bx=b.x-WOFF; if(bx>SW+4&&bx-WW>-4)bx-=WW; if(bx<-4-b.w&&bx+WW<SW+4)bx+=WW;
    if(bx<-40||bx>SW+40) continue;
    drawn++;
    var sw2=Math.min(b.w-4,34), sh2=13, sx=Math.round(bx+(b.w-sw2)/2), sy=HORIZON-b.h+8;   // mounted high on the facade
    if(curRegime&&curRegime.active&&curRegime.stage>=3){ drawStateScreen(g,sx,sy,sw2,sh2,now,L); continue; }   // STATE MEDIA takes the screens
    g.fillStyle=emerg?"#5a1418":(L>0.5?"#474d59":"#2a2f39"); g.fillRect(sx-1,sy-1,sw2+2,sh2+2);   // metallic bezel — reads against any facade
    g.fillStyle=emerg?"#170406":"#05070c"; g.fillRect(sx,sy,sw2,sh2);                             // dark screen
    g.fillStyle=emerg?"#7a1418":"#123a4e"; g.fillRect(sx,sy,sw2,4);                               // header bar
    drawUiText(g,hdr.substr(0,Math.max(1,(sw2/4)|0)),sx+1,sy,emerg?"#ffd2c4":"#bfe8ff",1);
    if((Math.floor(now/500))&1){ g.fillStyle=emerg?"#ff3b3b":"#ff5555"; g.fillRect(sx+sw2-3,sy+1,2,2); }   // blinking LIVE dot
    g.save(); g.beginPath(); g.rect(sx+1,sy+5,sw2-2,sh2-6); g.clip();                             // scrolling news line, clipped
    var tw2=(msg.length*4-1)+24, off=((now*0.02)+b.seed*7)%tw2, tcol=emerg?"#ff9a78":(night>0.5?"#7fe0ff":"#9ad4ff");
    drawUiText(g,msg,(sx+sw2-1-off)|0,sy+6,tcol,1);
    drawUiText(g,msg,(sx+sw2-1-off+tw2)|0,sy+6,tcol,1);
    g.restore();
    if(night>0.3){ g.globalCompositeOperation="lighter"; g.fillStyle=emerg?"rgba(255,60,50,0.12)":"rgba(90,180,255,0.10)"; g.fillRect(sx,sy,sw2,sh2); g.globalCompositeOperation="source-over"; }
  }
}

// ============================ CITY 9 NEWS — the rooftop jumbotrons ============================
// v1.38: GIANT screens mounted on masts ABOVE the skyline (clears the viaduct/crowd occlusion that
// swallows facade-level detail) carrying a pixel NEWS ANCHOR who reads the news, a READABLE two-line
// headline in a coloured lower-third, and a scrolling ticker. Scattered on a few downtown rooftops.
// The segment ROTATES across beats — POLITICS · BREAKING · MARKETS · CRIME · TECH · COSMOS · WEATHER ·
// CITY — and cuts to red BREAKING the instant anything happens. Builds on the same news sources as the
// facade screens (drawNewsScreens) + tickerMsg; distinct big rooftop presentation.
var NEWS_CATS=[
  {k:"POLITICS", c:"#e0b23a", hdr:"CITY 9 NEWS"},
  {k:"MARKETS",  c:"#3ac86a", hdr:"MONEY 9"},
  {k:"CRIME",    c:"#e0653a", hdr:"CITY 9 NEWS"},
  {k:"TECH",     c:"#4aa0e0", hdr:"TECH 9"},
  {k:"COSMOS",   c:"#a86ae0", hdr:"SKYWATCH 9"},
  {k:"WEATHER",  c:"#4ac8d0", hdr:"WX 9"},
  {k:"CITY",     c:"#c05ad0", hdr:"CITY 9 NEWS"},
  {k:"BUILD",    c:"#e0a83a", hdr:"CITY 9 NEWS"} ];
// the current on-air segment: {cat, color, hdr, kick, line} — kick = coloured kicker, line = headline body.
// PURE f(now): rotates on a ~9s slot; a live emergency preempts everything with red BREAKING.
function newsSegment(now){
  if(newsEmergency()){
    var bk="BREAKING", bl;
    if(cityPhase==="apoc"){ var mn=meteorNews(now); bl=mn?mn.replace(/^☄ ?/,""):("EVACUATE "+cityName+" NOW"); }
    else if(curDis) bl="CAT-"+curDis.intensity+" "+DIS_NAME[curDis.type]+(curDis.type==="rift"?" - "+riftInvaderNames(curDis)+" SIGHTED":"")+" - SEEK SHELTER";
    else if(curWar&&curWar.f>=0&&curWar.f<1) bl="INVASION UNDERWAY - SHELTER IN PLACE";
    else if(fireBurning) bl="WILDFIRE ON THE RIDGE - STAY CLEAR";
    else if(curBlk) bl="POWER OUT DOWNTOWN - CREWS EN ROUTE";
    else if(curOutbreak) bl="HEALTH EMERGENCY - MASKS ADVISED CITYWIDE";
    else bl="EMERGENCY - STAY TUNED";
    return {cat:"BREAKING", color:"#ff3b3b", hdr:"BREAKING NEWS", kick:bk, line:bl};
  }
  // under THE ORDER the screens are state media — a defiant/propaganda tone
  if(curRegime&&curRegime.active&&curRegime.stage>=3){
    var rbz=regimeBills();
    return {cat:"STATE", color:rbz?"#00338d":"#c0182a", hdr:rbz?"BILLS STATE TV":"STATE NEWS", kick:rbz?"BILLS MAFIA":"THE ORDER",
      line:regimeSlogansFor(curRegime)[(Math.floor(now/4200))%regimeSlogansFor(curRegime).length]};
  }
  // otherwise cycle the beats; each returns null when it has nothing, so we skip to the next with content
  var order=[0,1,2,3,4,5,6,7], slot=Math.floor(now/9000), tries=0, ci=slot%order.length;
  while(tries<order.length){
    var cat=NEWS_CATS[ci], seg=newsBeat(cat.k, now, slot);
    if(seg){ return {cat:cat.k, color:cat.c, hdr:cat.hdr, kick:seg[0], line:seg[1]}; }
    ci=(ci+1)%order.length; tries++;
  }
  return {cat:"CITY", color:"#c05ad0", hdr:"CITY 9 NEWS", kick:cityName.toUpperCase().substr(0,10), line:"POP "+popFmt(cityPop())+" AND GROWING"};
}
// content for one beat → [kicker, headline] or null. Reuses the live city state the ticker reads.
function newsBeat(cat, now, slot){
  var M=curMayor, appr=approvalNow(now), eco=curEcon;
  if(cat==="POLITICS"){
    if(M&&M.electionDay) return ["ELECTION DAY","POLLS OPEN - "+M.winName+" VS "+M.loseName];
    if(M&&M.debate) return ["DEBATE NIGHT",M.winName+" MEETS "+M.loseName+" AT CITY HALL"];
    if(M&&M.campaign) return ["CAMPAIGN","LATEST POLL - "+M.winName+" LEADS "+M.loseName];
    if(M&&M.justElected) return ["CITY HALL","MAYOR "+M.winName+" - "+M.party.k+" AGENDA"];
    if(M&&M.scandal) return ["SCANDAL",M.recallVote?"RECALL VOTE UNDERWAY":"CITY HALL ROCKED BY SCANDAL"];
    if(M) return ["CITY HALL","APPROVAL "+appr+" PCT FOR MAYOR "+M.winName];
    return null;
  }
  if(cat==="MARKETS"){
    var pb=peopleMarketBeat(now, slot); if(pb && (slot&1)) return pb;   // THE PEOPLE: real citizen-driven economy news, alternating with the market index
    var r=econReport(now), up=r.chg>=0, msub=(slot%3);
    if(msub===0) return [up?"MARKETS UP":"MARKETS DOWN", r.name+" "+(up?"+":"")+r.chg+"% - "+(r.boom?"BOOM ROLLS ON":r.bust?"RECESSION FEARS GROW":"MIXED SESSION")];
    if(msub===1) return ["JOB MARKET", r.jobs+" - UNEMPLOYMENT "+r.unemp+" PCT"];
    return ["THE ECONOMY", r.boom?"BUSINESSES EXPAND - CRANES OVER "+cityName:r.bust?"HIRING FREEZE - BELTS TIGHTEN":"STEADY GROWTH DOWNTOWN"];
  }
  if(cat==="CRIME"){
    var cr=crimeBeat(now); return cr;
  }
  if(cat==="TECH"){
    var tb=techBeat(now, slot); return tb;
  }
  if(cat==="COSMOS"){
    var nd=nowDate(), shw=currentShower(nd);
    if(shw) return ["SKYWATCH",shw.n+" SHOWER PEAKS TONIGHT - LOOK UP"];
    var issp=issAltAzNow(now); if(issp&&issp.alt>12&&dayPhase(nd).light<0.30) return ["SKYWATCH","THE ISS PASSES OVER "+cityName+" NOW"];
    if(curSpace>0.3) return ["SPACEPORT",cityName+" SPACEPORT - NEXT LAUNCH BOARDING"];
    var COS=[["ASTRONOMY","ASTRONOMERS SPOT A COMET OVER "+cityName],["COSMOS","A NEW EXOPLANET NAMED FOR "+cityName],["NIGHT SKY","AURORA FORECAST - CHECK THE NORTHERN HORIZON"]];
    return COS[slot%COS.length];
  }
  if(cat==="WEATHER"){
    var fx=wfx(), t=Math.round(weather.temp==null?60:weather.temp);
    if(fx.thunder) return ["SEVERE WX","THUNDERSTORM WARNING FOR "+cityName];
    if(fx.snow) return ["WINTER WX","SNOW - PLOWS DEPLOYED CITYWIDE - "+t+"F"];
    if(fx.rain||fx.drizzle) return ["WEATHER","RAIN CONTINUES - "+t+"F DOWNTOWN"];
    if(fx.fog) return ["WEATHER","DENSE FOG - LOW VISIBILITY DOWNTOWN"];
    if(fx.cloudy) return ["WEATHER",((weather.cloud||0)>=88?"OVERCAST":"CLOUDY")+" - "+t+"F"];
    return ["FORECAST","CLEAR SKIES - "+t+"F OVER "+cityName];
  }
  if(cat==="CITY"){
    var CTY=[["CITY LIFE","POP "+popFmt(cityPop())+" AND GROWING"],["TRANSIT",cityName+" TRANSIT - ALL LINES RUNNING"]];
    if(curEvents&&curEvents.parade) CTY.push(["EVENTS","PARADE TODAY ON MAIN STREET"]);
    if(curEvents&&curEvents.champ) CTY.push(["SPORTS",teamName+" WIN THE TITLE - PARADE DOWNTOWN"]);
    if(gameNight(nowDate())) CTY.push(["SPORTS","GAME NIGHT - "+cityName+" "+teamName+" AT 7"]);
    if(cityHasBuild("park")) CTY.push(["CITY LIFE","CITY PARK NAMED BEST NEW PUBLIC SPACE"]);
    return CTY[slot%CTY.length];
  }
  if(cat==="BUILD"){
    var fm=cityFirms(), fp=fm[slot%fm.length], er=econReport(now), bsub=(slot%3);
    if(er.boom){
      if(bsub===0) return ["DEVELOPMENT",fp.name+" BREAKS GROUND ON NEW TOWER"];
      if(bsub===1) return ["BUILDING BOOM","CRANES RISE ACROSS "+cityName+" SKYLINE"];
      return ["JOBS","BUILDERS HIRING - "+fp.name+" ADDS CREWS"];
    }
    if(er.bust){
      if(bsub===0) return ["SLOWDOWN",fp.name+" HALTS WORK - SITES STALL"];
      if(bsub===1) return ["CONSTRUCTION","BUILDING SLUMP HITS "+cityName];
      return ["LAYOFFS","CRANES IDLE AS DOWNTURN BITES"];
    }
    if(bsub===0) return ["OPENING","BUILT BY "+fp.name+" - RIBBON CUT DOWNTOWN"];
    if(bsub===1) return ["DEVELOPMENT",fp.name+" TOPS OUT NEW HIGH-RISE"];
    return ["CITY SKYLINE",fp.name+" WINS "+cityName+" BUILD OF THE YEAR"];
  }
  return null;
}
// a synthetic market index — a slow deterministic walk anchored to econOf so the board AGREES with the
// economy (boom = green climbing, bust = red falling), plus a small stable intraday wobble. Pure f(now).
function marketIndex(now){
  var e=econOf(now), base=1200+Math.round(e*2600);           // 1200 (bust) … 3800 (boom)
  var day=Math.floor(now/86400000), wob=((day*2654435761)>>>0)/4294967296;   // stable per-day wobble
  var chg=Math.round(((e-0.5)*9 + (wob-0.5)*4)*10)/10;       // pct: tracks the economy, small daily noise
  var nm=(cityName.replace(/[^A-Z]/gi,"").substr(0,3).toUpperCase()||"CTY")+"X";
  return {name:nm, val:base, chg:chg};
}
// v1.48 — the economy tracker: the market index + JOB MARKET status + UNEMPLOYMENT, all read off curEcon so
// the news AGREES with the street (boom→hiring/low-unemp/cranes; bust→layoffs/high-unemp/stalled sites).
function econReport(now){
  var e=econOf(now), idx=marketIndex(now);
  var jobs=e>0.62?"HIRING SURGE":e<0.38?"LAYOFFS ANNOUNCED":"JOBS STEADY";
  return {name:idx.name, val:idx.val, chg:idx.chg, unemp:(3.4+(1-e)*9.2).toFixed(1), jobs:jobs, boom:e>0.62, bust:e<0.38};
}
var TICKER_SYMS=["ZORP","NIMB","VOLT","GENO","APEX","LUXE","HALE","MERI","IRON","OMNI","NOVA","KYRA"];
function marketCrawl(now){                                     // a stock-ticker string of a few symbols +/- (tracks curEcon)
  var e=econOf(now), out="", base=Math.floor(now/45000);
  for(var i=0;i<6;i++){ var h=(((base+i*7919)*2654435761)>>>0)/4294967296, ch=Math.round(((e-0.5)*8+(h-0.5)*7)*10)/10;
    out+=TICKER_SYMS[(base+i)%TICKER_SYMS.length]+" "+(ch>=0?"+":"")+ch+"  "; }
  return out;
}
// CRIME beat — synthetic, keyed to the economy (busts raise crime) and the SAFETY levers already in play.
function crimeBeat(now){
  var e=econOf(now), slot=Math.floor(now/9000);
  if(curPolicies&&curPolicies.surveil) return ["SAFETY","SAFE-CAM NETWORK - POLICE REPORT CRIME DOWN"];
  if(cityHasBuild("casino")) return ["CRIME","EXTRA PATROLS ADDED AROUND THE CASINO DISTRICT"];
  var CR=e<0.4
    ? [["CRIME","BURGLARIES UP DOWNTOWN - POLICE URGE VIGILANCE"],["CRIME","POLICE CHIEF ASKS FOR MORE PATROLS"]]
    : [["POLICE BLOTTER","A QUIET NIGHT ON THE BEAT DOWNTOWN"],["SAFETY","NEIGHBORHOOD WATCH EXPANDS TO THE WATERFRONT"]];
  return CR[slot%CR.length];
}
// TECH / AI beat — synthetic future-flavour, deepens with the space age.
function techBeat(now, slot){
  var TB=[["TECH","A "+cityName+" STARTUP RAISES A ROUND - HIRING NOW"],
    ["AI","CITY ROLLS OUT AN AI TRAFFIC PILOT DOWNTOWN"],
    ["TECH","FIBER REACHES THE LAST NEIGHBORHOOD THIS WEEK"]];
  if(curSpace>0.4) TB.push(["SPACE TECH","ORBITAL FACTORY SHIPS ITS FIRST PARTS HOME"]);
  if(curRegime&&curRegime.active) TB.push(["SURVEILLANCE","NEW CAMERAS GO LIVE ACROSS THE CENTRE"]);
  return TB[slot%TB.length];
}
// draw a small pixel NEWS ANCHOR bust (head + hair + suit + desk) inside a screen region, "talking".
function drawAnchor(g,ax,ay,now,skin){
  var talk=(Math.floor(now/220))%3;                          // mouth opens/closes → reads as speaking
  g.fillStyle="#2a2438"; g.fillRect(ax-1,ay+7,12,7);         // suit shoulders
  g.fillStyle="#efe9df"; g.fillRect(ax+3,ay+7,4,7);          // shirt/collar V
  g.fillStyle=skin.c; g.fillRect(ax+2,ay+1,6,6);             // face
  g.fillStyle=skin.sh; g.fillRect(ax+2,ay+1,1,6);            // cheek shade
  g.fillStyle=skin.hair; g.fillRect(ax+1,ay,8,2); g.fillRect(ax+1,ay+1,1,3); g.fillRect(ax+8,ay+1,1,3);   // hair
  g.fillStyle="#20242c"; g.fillRect(ax+3,ay+3,1,1); g.fillRect(ax+6,ay+3,1,1);   // eyes
  g.fillStyle="#7a4a44"; if(talk===0) g.fillRect(ax+4,ay+5,2,1); else g.fillRect(ax+4,ay+5,2,2);   // mouth (opens)
}
// a 1px pixel diagonal (Bresenham) — used for the billboard's cross-bracing so it reads as a steel truss.
function trussLine(g,x1,y1,x2,y2){
  var dx=Math.abs(x2-x1), dy=Math.abs(y2-y1), sx=x1<x2?1:-1, sy=y1<y2?1:-1, err=dx-dy, x=x1,y=y1;
  for(var n=0;n<200;n++){ g.fillRect(x|0,y|0,1,1); if(x===x2&&y===y2) break; var e2=2*err; if(e2>-dy){err-=dy;x+=sx;} if(e2<dx){err+=dx;y+=sy;} }
}
// ADS + SHOWS a screen can run instead of news (Nick: each screen its own channel; not all news).
var AD_POOL=[
  {kick:"ZORP COLA", line:"TASTE THE FIZZ", color:"#e04a4a", art:"can"},
  {kick:"NIMBUS AIR", line:"FLY HIGHER TODAY", color:"#4aa0e0", art:"plane"},
  {kick:"VOLT MOTORS", line:"DRIVE THE FUTURE", color:"#e0b23a", art:"car"},
  {kick:"BLOOM BURGERS", line:"NOW OPEN DOWNTOWN", color:"#e0653a", art:"burger"},
  {kick:"LUXE 9 PHONE", line:"THE FUTURE IN HAND", color:"#c05ad0", art:"phone"},
  {kick:"GIGA GYM", line:"FIRST MONTH FREE", color:"#3ac86a", art:"gym"} ];
var SHOW_POOL=[
  {net:"CH 12", kick:"THE MAYORS", line:"NEW EPISODE 9PM", color:"#c05ad0", art:"drama"},
  {net:"CH 7",  kick:"COP CITY",   line:"NOW PLAYING",     color:"#4a90e0", art:"drama"},
  {net:"CH 5",  kick:"GARDEN HOUR",line:"LIVE FROM THE PARK",color:"#3ac86a", art:"garden"},
  {net:"CH 21", kick:"STAR VOYAGE",line:"SEASON FINALE",    color:"#4aa0e0", art:"space"},
  {net:"CH 3",  kick:"CATCH IT",   line:"GAME SHOW TONIGHT",color:"#e0b23a", art:"quiz"},
  {net:"CH 9",  kick:"LATE LAUGHS",line:"COMEDY HOUR",      color:"#e0653a", art:"drama"} ];
// what a given screen (identified by its host-tower seed) is showing right now. Each screen runs an
// INDEPENDENT channel, offset by its seed so neighbouring screens differ: ~70% news (category varied per
// screen), ~20% ad, ~10% a TV show. A live emergency + STATE media override every screen at once.
function screenContent(seed, now){
  if(curBills) return {type:"ad", c:{kick:"GO BILLS!", line:BILLS_SLOGANS[((Math.floor(now/5000)+((seed>>>3)%BILLS_SLOGANS.length))%BILLS_SLOGANS.length)], color:BILLS_BLUE, art:"ball"}};   // gameday: the big screens go Bills
  if((curRegime&&curRegime.active&&curRegime.stage>=3) || newsEmergency()) return {type:"news", seg:newsSegment(now)};
  var key=((seed*2654435761)>>>0);
  var pslot=Math.floor(now/12000)+(key%6);            // this screen's programme index — offset by seed so screens are OUT OF PHASE, advances every ~12s so each one cycles news→ad→show over time
  var roll=((key+pslot*7)>>>0)%10, sub=pslot;
  if(roll<2) return {type:"ad", c:AD_POOL[sub%AD_POOL.length]};
  if(roll<3) return {type:"show", c:SHOW_POOL[sub%SHOW_POOL.length]};
  var ci=((key+pslot)>>>0)%NEWS_CATS.length, tries=0, beat=null, cat;
  while(tries<NEWS_CATS.length){ cat=NEWS_CATS[ci]; beat=newsBeat(cat.k, now, pslot+seed); if(beat) break; ci=(ci+1)%NEWS_CATS.length; tries++; }
  if(!beat){ cat=NEWS_CATS[0]; beat=["CITY","POP "+popFmt(cityPop())+" AND GROWING"]; }
  return {type:"news", seg:{cat:cat.k, color:cat.c, hdr:cat.hdr, kick:beat[0], line:beat[1]}};
}
// a small pixel graphic for an ad / show, centred at (cx,cy).
function drawScreenArt(g,cx,cy,kind,col,now){
  g.fillStyle=col;
  if(kind==="can"){ g.fillRect(cx-3,cy-6,6,12); g.fillStyle="#dfe6ee"; g.fillRect(cx-3,cy-2,6,3); g.fillStyle=col; g.fillRect(cx-1,cy-8,2,2); }
  else if(kind==="plane"){ g.fillRect(cx-6,cy-1,13,2); g.fillRect(cx+2,cy-4,2,8); g.fillRect(cx-6,cy-3,2,3); }
  else if(kind==="car"){ g.fillRect(cx-6,cy,12,4); g.fillRect(cx-3,cy-3,7,3); g.fillStyle="#12151b"; g.fillRect(cx-4,cy+4,2,2); g.fillRect(cx+3,cy+4,2,2); }
  else if(kind==="burger"){ g.fillStyle="#d8a24a"; g.fillRect(cx-5,cy-4,10,3); g.fillStyle="#5a3a22"; g.fillRect(cx-5,cy-1,10,2); g.fillStyle="#3ac86a"; g.fillRect(cx-5,cy+1,10,1); g.fillStyle="#d8a24a"; g.fillRect(cx-5,cy+2,10,3); }
  else if(kind==="phone"){ g.fillStyle="#20242c"; g.fillRect(cx-4,cy-7,8,14); g.fillStyle=col; g.fillRect(cx-3,cy-5,6,9); }
  else if(kind==="gym"){ g.fillRect(cx-6,cy-1,12,2); g.fillRect(cx-6,cy-3,2,6); g.fillRect(cx+4,cy-3,2,6); }
  else if(kind==="drama"){ g.fillStyle="#e8b890"; g.fillRect(cx-6,cy-3,5,6); g.fillStyle="#8a5a3a"; g.fillRect(cx+1,cy-3,5,6); g.fillStyle=col; g.fillRect(cx-6,cy+3,5,2); g.fillRect(cx+1,cy+3,5,2); }
  else if(kind==="garden"){ g.fillStyle="#e0c040"; g.fillRect(cx+3,cy-6,3,3); g.fillStyle="#6a4a2a"; g.fillRect(cx-4,cy-1,2,5); g.fillStyle="#3ac86a"; g.fillRect(cx-7,cy-5,8,5); }
  else if(kind==="space"){ g.fillStyle="#cfd8e2"; g.fillRect(cx-1,cy-6,3,9); g.fillStyle=col; g.fillRect(cx-1,cy-8,3,3); g.fillStyle="#e0653a"; g.fillRect(cx-1,cy+3,3,3); g.fillStyle="#fff"; g.fillRect(cx-6,cy-4,1,1); g.fillRect(cx+5,cy-1,1,1); }
  else if(kind==="quiz"){ g.fillStyle=col; g.fillRect(cx-2,cy-6,5,2); g.fillRect(cx+1,cy-4,2,3); g.fillRect(cx-1,cy-1,3,2); g.fillRect(cx-1,cy+3,3,2); }
  else if(kind==="ball"){ g.fillStyle="#7a3b18"; g.fillRect(cx-5,cy-2,10,5); g.fillRect(cx-6,cy-1,1,3); g.fillRect(cx+5,cy-1,1,3);   // a football
    g.fillStyle="#f4f0e6"; g.fillRect(cx-2,cy,4,1); g.fillRect(cx-1,cy-1,1,3); g.fillRect(cx+1,cy-1,1,3); }                          // white laces
}
// mount + draw ONE rooftop jumbotron. (rx,ry) = screen top-left in SCREEN space; roofY = the roof it stands on.
// seed = the host tower's seed → picks this screen's independent channel (so neighbours differ).
function drawJumbotron(g,rx,ry,sw,sh,roofY,now,L,seed){
  var content=screenContent(seed,now), type=content.type, night=1-L, col, hdr, brk=false, seg=null;
  if(type==="news"){ seg=content.seg; col=seg.color; hdr=seg.hdr; brk=(seg.cat==="BREAKING"); }
  else if(type==="ad"){ col=content.c.color; hdr="ADVERT"; }
  else { col=content.c.color; hdr=content.c.net; }
  // ---- the SUPPORT STRUCTURE: a full-width braced steel frame planted flush on the roof. Legs run to the
  //      screen's OUTER EDGES (nothing overhangs unsupported) + inner legs + X-bracing + a base sill bolted
  //      across the whole rooftop footprint → reads as a billboard rigidly ATTACHED, not perched on stilts. ----
  var beamY=ry+sh, botY=roofY;
  g.fillStyle="#20242b"; g.fillRect(rx-2,botY-2,sw+4,3);      // base sill spanning the full footprint, flush on the roof
  var legs=[rx+1, rx+Math.round(sw*0.34), rx+Math.round(sw*0.66), rx+sw-3];   // 4 legs; the outer two sit under the screen edges (no overhang)
  g.fillStyle="#333942";
  g.fillRect(rx,beamY,sw,2);                                 // top beam runs the FULL screen width
  var mY=(beamY+botY)>>1; g.fillRect(rx+1,mY,sw-2,1);         // mid horizontal member ties the legs
  for(var lg=0;lg<legs.length;lg++) g.fillRect(legs[lg]-1,beamY,3,botY-beamY);   // thick legs
  g.fillStyle="#2a2f37";                                     // X cross-bracing in every bay (upper + lower halves)
  for(var lb=0;lb<legs.length-1;lb++){ var a=legs[lb], b=legs[lb+1];
    trussLine(g,a,mY,b,beamY); trussLine(g,b,mY,a,beamY);     // upper-bay X
    trussLine(g,a,botY,b,mY);  trussLine(g,b,botY,a,mY);      // lower-bay X
  }
  g.fillStyle="#20242b"; for(var lf=0;lf<legs.length;lf++) g.fillRect(legs[lf]-2,botY-1,5,2);   // gusset foot plates bolting each leg down
  // bezel + backdrop
  g.fillStyle=brk?"#4a0a0e":"#0b0f18"; g.fillRect(rx-2,ry-2,sw+4,sh+4);   // dark bezel
  var bg=(type==="ad")?"#10121c":(type==="show")?"#0a0f1e":"#0c1524";
  g.fillStyle=bg; g.fillRect(rx,ry,sw,sh);                   // studio/programme backdrop
  g.fillStyle="#12203a"; for(var s=0;s<sh;s+=3) g.fillRect(rx,ry+s,sw,1);   // faint scanlines
  // header bar (channel identity)
  g.fillStyle=col; g.fillRect(rx,ry,sw,6);
  drawUiText(g,hdr.substr(0,Math.max(1,((sw-20)/4)|0)),rx+2,ry+1,brk?"#ffffff":"#0a0f18",1);
  if(type==="news"){ if((Math.floor(now/500))&1){ g.fillStyle="#ff3b3b"; g.fillRect(rx+sw-19,ry+1,3,3); } drawUiText(g,"LIVE",rx+sw-15,ry+1,"#ffe0e0",1); }
  else drawUiText(g,type==="ad"?"AD":"TV",rx+sw-9,ry+1,"#0a0f18",1);
  // ⚠⚠ NOTHING DRAWS OUTSIDE THE GLASS. Nick: "make sure the screens display all the text." Every
  // string here was truncated by a character count derived from the width — `per` — and one of them
  // (the wrapped headline) was never truncated at all, so a long line simply ran off the bezel and
  // out over the city. A character budget is a guess about a proportional problem; a CLIP is the
  // guarantee. Both now: the budget keeps text inside the panel it belongs to, and the clip means a
  // miscalculated budget can never again spill pixels onto the skyline.
  // ⚠ The drawable width is what is left after the 6px left inset AND a matching right margin —
  // `(sw-8)/4` counted the inset once and gave every line two characters more room than it had.
  // ⚠⚠ AND THE THREE LINES WERE PRINTING ON TOP OF EACH OTHER. This is the actual reason his screen
  // was unreadable, and it took a 400% crop to see it: the lower third is 16px tall with rows at +1,
  // +6 and +11, which assumes a 5px line. The pixel font needs SIX, so every row bled into the one
  // below it and the headline came out as two words superimposed. Truncating strings was never going
  // to fix a leading problem — I nearly shipped a character-budget fix for a line-height bug.
  var per=Math.max(4,((sw-12)/4)|0), ly=ry+sh-24, lh=20, kick, line;   // 3 rows at 6px + the ticker below
  g.save(); g.beginPath(); g.rect(rx,ry,sw,sh); g.clip();
  if(type==="news"){
    var skin=ANCHOR_SKINS[(((seed>>>3))%ANCHOR_SKINS.length)];    // each channel its own anchor
    drawAnchor(g,rx+(sw>>1)-5,ry+9,now,skin);
    g.fillStyle="#141b2c"; g.fillRect(rx,ry+sh-25,sw,3); g.fillStyle=col; g.fillRect(rx,ry+sh-25,sw,1);   // desk bar
    kick=seg.kick; line=seg.line;
  } else {
    // AD / SHOW: a big centred graphic in the upper area, title card in the lower third
    var scx=rx+(sw>>1), scy=ry+18;
    if(night>0.2){ g.globalCompositeOperation="lighter"; g.fillStyle=hexA(col,0.10); g.fillRect(rx,ry+6,sw,sh-26); g.globalCompositeOperation="source-over"; }
    drawScreenArt(g,scx,scy,content.c.art,col,now);
    kick=content.c.kick; line=content.c.line;
  }
  // lower-third band — kicker + up to two static, READABLE lines (no scroll: legibility is the point)
  g.fillStyle="#0a1220"; g.fillRect(rx,ly,sw,lh);
  g.fillStyle=col; g.fillRect(rx,ly,3,lh);
  drawUiText(g,kick.substr(0,per),rx+6,ly+1,col,1);
  var wrapped=wrapNews(line, per);
  drawUiText(g,wrapped[0].substr(0,per),rx+6,ly+8,"#eef4ff",1);
  if(wrapped[1]) drawUiText(g,wrapped[1].substr(0,per),rx+6,ly+14,"#cfe0f2",1);
  // STOCK-TICKER CRAWL along the very bottom (a live market ticker, green boom / red bust) — the economy tracker
  var cyb=ry+sh-4, r2=econReport(now), tcol=r2.boom?"#7dff9e":r2.bust?"#ff7d7d":"#ffd27d";
  g.fillStyle="#05070c"; g.fillRect(rx,cyb,sw,4);
  g.save(); g.beginPath(); g.rect(rx+1,cyb,sw-2,4); g.clip();
  var crawl=marketCrawl(now), cwid=(crawl.length*4-1)+16, coff=((now*0.02)+rx*3)%cwid;
  drawUiText(g,crawl,(rx+sw-1-coff)|0,cyb,tcol,1);
  drawUiText(g,crawl,(rx+sw-1-coff+cwid)|0,cyb,tcol,1);
  g.restore();
  // ⚠ AND IT HAS TO LOOK LIVE. "Make it look better and more dynamic." A panel of static text with one
  // blinking dot is a poster. What a real screen does is REFRESH: a bright band sweeps down the
  // picture, the whole thing flickers when the feed hiccups, and the frame around it is lit.
  var swp=((now*0.045+seed*37)%(sh+40))-20;                     // the refresh band, drifting down the glass
  if(swp>0&&swp<sh){ g.globalCompositeOperation="lighter";
    g.fillStyle="rgba(150,200,255,0.055)"; g.fillRect(rx,ry+(swp|0),sw,Math.max(1,(sh*0.10)|0));
    g.globalCompositeOperation="source-over"; }
  var flick=((((now/220)|0)*2654435761+seed)>>>0)%97;           // a rare dropped frame
  if(flick<2){ g.fillStyle="rgba(120,160,220,0.10)"; g.fillRect(rx,ry,sw,sh); }
  g.restore();                                                  // …end of the clip: the glass is finished
  // screen glow at night
  if(night>0.25){ g.globalCompositeOperation="lighter"; g.fillStyle=(brk?"rgba(255,60,50,":"rgba(90,170,255,")+(0.06+0.09*night).toFixed(2)+")"; g.fillRect(rx,ry,sw,sh); g.globalCompositeOperation="source-over"; }
  // a lit bezel, so the screen throws light on its own frame rather than sitting in a dead black box
  if(night>0.2){ g.globalCompositeOperation="lighter"; g.fillStyle=hexA(col,0.16*night);
    g.fillRect(rx-2,ry-2,sw+4,2); g.fillRect(rx-2,ry+sh,sw+4,2);
    g.globalCompositeOperation="source-over"; }
}
var ANCHOR_SKINS=[{c:"#e8b890",sh:"#cf9c74",hair:"#3a2a1e"},{c:"#c98a5e",sh:"#a86f48",hair:"#221812"},
  {c:"#8a5a3a",sh:"#6e442c",hair:"#161010"},{c:"#f0cfa8",sh:"#d8b088",hair:"#5a4632"}];
function wrapNews(str, per){
  if(str.length<=per) return [str,""];
  var cut=str.lastIndexOf(" ",per); if(cut<per*0.5) cut=per;
  return [str.substr(0,cut), str.substr(cut).replace(/^ /,"")];
}
// place a few BIG jumbotrons on downtown rooftops — tall, wide towers, spread across the view so they
// read as scattered. Standing-tower predicate (mirrors drawLayer) so a screen never floats over an empty
// plot; dies with its tower in the cataclysm. NONEWSTV suppresses it for the containment A/B guard.
function drawJumbotrons(g,L,now,night){
  if(curNoAds) return;      // no rooftop jumbotrons

  if(NONEWSTV || cityG<0.55) return;
  var sw=74, sh=50, placed=[], drawn=0, lastX=-999;
  for(var i=0;i<near.blds.length && drawn<3;i++){ var b=near.blds[i];
    if(b.type==="park"||b.h<40||b.w<16) continue;                          // a tall, wide downtown tower
    if(((b.seed>>>6)%5)!==0) continue;                                      // only some rooftops carry a jumbotron
    if(overSite(b.x,b.w)||overLandmark(b.x,b.w)) continue;                  // plot holds a site / civic landmark
    if(b.bAge!==undefined && cityG-b.bAge<=bandOf(b)) continue;             // tower not built yet
    if(apocHit(b.x)) continue;                                             // gone once the tower is destroyed
    var bx=b.x-WOFF; if(bx>SW+4&&bx-WW>-4)bx-=WW; if(bx<-4-b.w&&bx+WW<SW+4)bx+=WW;
    var cx=bx+(b.w>>1), rx=Math.round(cx-(sw>>1));
    if(rx<-sw||rx>SW) continue;
    if(Math.abs(cx-lastX)<sw+30) continue;                                  // spread them out
    var roofY=HORIZON-b.h, ry=roofY-14-sh;                                  // the truss lifts the screen a clear span above the roof
    if(ry<6){ ry=6; roofY=Math.min(roofY,ry+sh+14); }                       // keep it on-canvas (and the truss sane)
    // ⚠⚠ AND IT MUST NOT STRADDLE THE ELEVATED LINE. Nick: "make sure the trains go behind it lol."
    // My first fix moved the whole draw call after the train service pass — and a test caught it
    // immediately: `drawJumbotrons must stay behind train stations` is a DELIBERATE invariant, and it
    // is right, because a platform canopy genuinely is in front of a tower behind it. The draw order
    // was never the problem. The PLACEMENT was: a screen hung off a short tower can sit straight
    // across the viaduct, and then a train runs through its face no matter which order they draw in.
    // Two things cannot occupy the same band. Skip the rooftop instead — there is always another.
    if(!curVillage && gstage(0.42,0.58)>0){
      var vTy=(HORIZON-Math.round(GROUND*1.1))|0;                           // the deck, as drawTrainLine computes it
      if(roofY>vTy-4 && ry<vTy+8) continue;                                 // the screen would straddle the line
    }
    drawJumbotron(g,rx,ry,sw,sh,roofY,now,L,b.seed);
    lastX=cx; drawn++;
  }
}

// the OPEN SEA at the coast: land simply ends at a beach and the water runs on
// natural water body: smooth depth gradient + rolling two-tone swell (shared by sea & harbour).
// Crests are short drifting dashes whose speed/density grow toward the viewer — no grid pattern.
function waterTex(g,xa,xb,yTop,yBot,L,now){
  var w=xb-xa, h=yBot-yTop; if(w<=0||h<=0) return;
  var day=L>0.5, deep=mixc([26,58,84],[92,152,188],L);
  if(goldenK>0.05) deep=mixc(deep,goldC,goldenK*0.22);   // golden-hour water
  var sg2=g.createLinearGradient(0,yTop,0,yBot);
  sg2.addColorStop(0,css(mixc(deep,[168,196,224],day?0.3:0.14)));    // soft at the far edge…
  sg2.addColorStop(0.22,css(mixc(deep,[120,168,208],day?0.18:0.07)));
  sg2.addColorStop(0.55,css(deep));
  sg2.addColorStop(1,css(mixc(deep,day?[8,18,34]:[16,32,54],0.45))); // …deep, but readable at night
  g.fillStyle=sg2; g.fillRect(xa,yTop,w,yBot-yTop);
  g.fillStyle=day?"rgba(255,255,255,0.12)":"rgba(140,175,215,0.08)"; g.fillRect(xa,yTop,w,1);
  for(var y=yTop+2;y<yBot;y+=2){ var dpt=(y-yTop)/h;                 // the SWELL, row by row
    var stride=(QUAL===0?8:6)+((y*13)%4)-((dpt*3)|0);                // irregular spacing, denser up close
    var drift=Math.floor(now*(0.0030+dpt*0.0048)) + ((Math.sin(y*0.9)*5)|0); // gentle swell at the smooth water cadence
    var ca=(day?0.05:0.045)+dpt*(day?0.09:0.06);
    for(var x=xa+(((drift%stride)+stride)%stride); x<xb-1; x+=stride){
      var pk=Math.sin((x+drift*0.4)*0.05+y*0.47+now*0.00035);        // the sea moves in PATCHES —
      if(pk<-0.15) continue;                                         // calm lanes between the chop
      var aa3=ca*(0.45+0.55*pk);
      var cl=1+((x*7+y*13)&1);                                       // 1-2px crest dashes, irregular
      g.fillStyle="rgba(255,255,255,"+aa3.toFixed(3)+")"; g.fillRect(x,y,cl,1);
      g.fillStyle="rgba(6,14,30,"+(0.05+dpt*0.09).toFixed(3)+")";
      g.fillRect(x+((x+y)&1?-1:cl),y+1,cl,1);                        // shadowed trough beside it
    }
  }
  if(!day){                                                          // STARLIGHT rides the water at night
    g.globalCompositeOperation="lighter";
    for(var sg3=xa+3;sg3<xb-2;sg3+=12){ var hh7=((sg3*2654435761)>>>0);
      var tw2=Math.sin(now*0.0016+(hh7%97));
      if(tw2>0.55){ g.fillStyle="rgba(190,214,255,"+(0.10+0.16*(tw2-0.55)).toFixed(3)+")";
        g.fillRect(sg3,yTop+2+(hh7>>>4)%(h-3|0||1),1,1); } }
    g.globalCompositeOperation="source-over";
  }
}
// the mountains lean into the water: their silhouette mirrored as a soft dark reflection.
// Uses the cached ridge profile, so it costs one translucent column per pixel.
function drawMtsReflection(g,xa,xb,yTop,maxD,L){
  if(!mts||!mtsCache) return;
  var day=L>0.5;
  g.fillStyle=day?"rgba(52,66,96,0.20)":"rgba(6,10,22,0.30)";
  var a=Math.max(0,xa|0), b=Math.min(SW,xb|0);
  for(var sx=a;sx<b;sx++){
    var rh=mtsCache.h[1][sx]; if(mtsCache.h[0][sx]*0.8>rh) rh=mtsCache.h[0][sx]*0.8;
    if(rh<3) continue;
    var refH=Math.min(maxD,(rh*0.36)|0);
    if(((sx*11)&7)===0) refH-=1;                                     // ripple-broken edge
    if(refH>0) g.fillRect(sx,yTop+1,1,refH);
  }
}
// THE TIDE — a real one. Semidiurnal on the LUNAR day (12h25m, not 12h), with SPRINGS at new and
// full moon and NEAPS at the quarters, off the same `moonPhase` the sky already draws. Returns
// -1 (dead low) .. +1 (high). Nick's call, and it obeys the same rule every accent in this engine
// obeys: the real measurement drives it. On the sea cliffs the difference between low and high water
// is the difference between a shore with tide pools and kelp on it and a shore with none.
function tideLevel(now,nd){
  var ph=((now%44714000)/44714000)*Math.PI*2;                 // 12h25.2m, the semidiurnal beat
  var mp=moonPhase(nd||nowDate());
  var spring=Math.abs(Math.cos(mp*Math.PI*2));                // 1 at new/full · 0 at the quarters
  return Math.sin(ph)*(0.52+0.48*spring);
}
// WHAT THE TIDE UNCOVERS. Nick, on the sea cliffs being the weakest of the seven: put the sea back
// in frame at their foot — surf on rock, tide pools, kelp, seals and gulls actually on the water.
// All of it keys off `tideK`, so at high water the pools and the kelp are simply GONE and the seals
// have left; a still frame at high tide correctly shows almost none of this, which is the point.
function drawShoreLife(g,ex,side,wTop,depth,tideK,L,now,xa,xb){
  var K=Math.max(1,KSP), day=L>0.5;
  var low=Math.max(0,-tideK);                                  // 0 at high water, 1 at dead low
  var rock=day?"#6e7278":"#22262c", rock2=day?"#585c62":"#171a1f";
  // SURF ON THE ROCK — bursts where the swell hits, at any tide, harder in real wind.
  var wind=(weather.wind==null?5:weather.wind), surfK=Math.min(1.6,0.5+wind/16);
  for(var s=0;s<7;s++){
    var sy=wTop+Math.round(((s*37)%Math.max(1,depth-4))+2);
    var burst=Math.sin(now*0.0022+s*1.9);
    if(burst<0.45) continue;
    var bx=ex-side*Math.round((1+((s*13)%4))*K);
    var bh=Math.round((2+burst*5)*K*surfK);
    // ⚠ A vertical bar crossed by a horizontal one renders as a PLUS SIGN — it read as a crosshair
    // floating on the rock, not as water hitting it. A splash is a fan: widest at the base where it
    // strikes, thinning and scattering as it goes up.
    var a9=(0.30+0.35*(burst-0.45)/0.55);
    for(var by=0;by<bh;by++){
      var bf=by/bh, spread=Math.round((1-bf)*3*K)+1;
      g.fillStyle="rgba(255,255,255,"+(a9*(1-bf*0.7)).toFixed(2)+")";
      g.fillRect(bx-spread,sy-by,spread*2,Math.max(1,Math.round(K)));
    }
    for(var dq=0;dq<3;dq++){                                    // and a few drops thrown clear of it
      var dh=((s*97+dq*31)>>>0);
      g.fillStyle="rgba(255,255,255,"+(a9*0.7).toFixed(2)+")";
      g.fillRect(bx-side*Math.round(((dh%5)+1)*K),sy-bh-Math.round(((dh>>>4)%4)*K),Math.max(1,Math.round(K)),Math.max(1,Math.round(K)));
    }
  }
  if(low<0.10) return;                                         // high water: the rest of this is under the sea
  // TIDE POOLS on the rock the sea has just left, each with a bright rim and something living in it.
  for(var p=0;p<6;p++){
    var h=((p*2654435761+((xa*31)|0))>>>0);
    var py=wTop+Math.round(((h%Math.max(1,depth-6))+3));
    var px=ex-side*Math.round((3+(h>>>7)%9)*K*low);
    if(px<xa-4||px>xb+4) continue;
    var pw=Math.round((3+((h>>>13)%5))*K), pht=Math.max(1,Math.round(1.6*K));
    g.fillStyle=day?"rgba(58,104,110,0.85)":"rgba(14,28,34,0.85)";
    g.fillRect(px-pw,py,pw*2,pht);
    g.fillStyle=day?"rgba(178,196,196,0.6)":"rgba(70,86,96,0.5)";   // the wet rim catching the light
    g.fillRect(px-pw,py-Math.max(1,Math.round(K*0.7)),pw*2,Math.max(1,Math.round(K*0.7)));
    if((h>>>19)&1){ g.fillStyle=day?"#c0603e":"#3a1c12";             // a starfish in it
      g.fillRect(px-Math.round(K),py,Math.round(2*K),Math.max(1,Math.round(K))); }
  }
  // KELP, lying flat and glistening where it has been left dry, still swaying where it has not.
  for(var kq=0;kq<9;kq++){
    var kh=((kq*40503+((xa*7)|0))>>>0);
    var ky=wTop+Math.round((kh%Math.max(1,depth-3))+2);
    var kx=ex-side*Math.round((1+(kh>>>5)%7)*K);
    if(kx<xa-6||kx>xb+6) continue;
    var kl=Math.round((4+((kh>>>11)%7))*K), lying=low>0.55;
    g.fillStyle=day?"rgba(66,74,38,0.9)":"rgba(16,20,12,0.9)";
    for(var kb=0;kb<kl;kb++){
      var kf=kb/kl;
      var kdx=lying? Math.round(-side*kb) : Math.round(Math.sin(now*0.0018+kq)*kf*2.6*K);
      var kdy=lying? Math.round(Math.sin(kf*3.0)*1.4*K) : -kb;
      g.fillRect(kx+kdx,ky+kdy,Math.max(1,Math.round(1.4*K)),Math.max(1,Math.round(K)));
    }
  }
  if(low<0.35) return;
  // SEALS HAULED OUT. They come up on the exposed rock and lie there, and one lifts its head now and
  // then. `drawQuad` draws standing animals; a hauled-out seal is a different posture entirely.
  for(var sl=0;sl<3;sl++){
    var sh=((sl*7919+((xa*13)|0))>>>0);
    var sy2=wTop+Math.round((sh%Math.max(1,depth-8))+5);
    var sx2=ex-side*Math.round((5+(sh>>>9)%11)*K*low);
    if(sx2<xa-8||sx2>xb+8) continue;
    var sw2=Math.round((7+((sh>>>15)%4))*K), sh2=Math.max(2,Math.round(2.4*K));
    g.fillStyle=day?"#7c7a76":"#26262a";
    g.fillRect(sx2-sw2/2,sy2,sw2,sh2);                                        // the body, low and long
    g.fillStyle=day?"#63615e":"#1b1b1f";
    g.fillRect(sx2-sw2/2,sy2+sh2,Math.round(sw2*0.35),Math.max(1,Math.round(K)));   // the tail flippers
    var lift=(Math.floor(now/2600)+sl)%4===0?Math.round(2*K):0;               // …and the head, lifting
    g.fillStyle=day?"#87857f":"#2b2b30";
    g.fillRect(sx2+sw2/2-Math.round(2*K),sy2-lift-Math.round(K),Math.round(2.4*K),Math.max(1,Math.round(1.8*K)));
  }
  // GULLS standing on the wet sand — the ones in the air already key off hasOcean elsewhere.
  for(var gq=0;gq<5;gq++){
    var gh=((gq*104729+((xa*17)|0))>>>0);
    var gy3=wTop+Math.round((gh%Math.max(1,depth-4))+3);
    var gx3=ex-side*Math.round((2+(gh>>>7)%13)*K*low);
    if(gx3<xa-4||gx3>xb+4) continue;
    var step=((Math.floor(now/700)+gq)%5===0)?Math.round(K):0;
    g.fillStyle=day?"#eef1f5":"#4a5058";
    g.fillRect(gx3+step,gy3-Math.round(2*K),Math.max(1,Math.round(2*K)),Math.round(2*K));
    g.fillStyle=day?"#3a4048":"#20242a";
    g.fillRect(gx3+step,gy3,Math.max(1,Math.round(K)),Math.max(1,Math.round(K)));
  }
}
function drawOpenSea(g,L,now,night){
  if(!hasOcean||seaW<=0) return;
  // How far BACK the water goes. Higher on screen is further away here, so this is the depth of the
  // bay, not just a stripe. 22px is right for a city that merely happens to have a waterfront; on the
  // SEA CLIFFS the water is the point, and a 22px strip behind the harbour sheds is why that land
  // read as a grey wall with no sea in it at all.
  var wTop=HORIZON-(curBiome.k==="cliffs"?Math.round(54*Math.max(1,KSP)):22), day=L>0.5;
  var sand=day?[216,196,150]:[86,80,64], wet=day?[168,148,110]:[62,58,46];
  var depth=(roadFNow()>0.5)?(HORIZON-wTop):(SH-wTop);        // before the causeway is paved, water runs to the screen bottom
  var bands=[[0,WW*seaW,+1],[WW*(1-seaW),WW,-1]];
  for(var bi2=0;bi2<bands.length;bi2++){ var A=bands[bi2][0], B=bands[bi2][1], side=bands[bi2][2];
    for(var w2=-1;w2<=1;w2++){ var xa=Math.max(0,(A-WOFF+w2*WW)|0), xb=Math.min(SW,(B-WOFF+w2*WW)|0);
      if(xb<=xa) continue;
      waterTex(g,xa,xb,wTop,wTop+depth,L,now);
      drawMtsReflection(g,xa,xb,wTop,depth-2,L);               // the range mirrored in the sea
      var ex=((side>0? B : A)-WOFF+w2*WW)|0;                   // the land's edge
      // …and where the WATER's edge is right now. The land does not move; the sea does. On the sea
      // cliffs the range is wide enough to expose a real shore at low water and drown it at high.
      var tideK=tideLevel(now,nowDate());
      var tideR=Math.round(((curBiome.k==="cliffs"||curBiome.k==="beach")?11:4)*Math.max(1,KSP));
      var tideX=Math.round(tideK*tideR)*side;                   // high water advances onto the land
      ex+=tideX;
      if(ex<-10||ex>SW+10) continue;
      for(var sy=wTop;sy<wTop+depth;sy++){                     // the BEACH — a meandering, lapping shoreline
        var dp2=(sy-wTop)/depth;
        var curve=Math.sin(sy*0.16+A*0.3)*1.6+Math.sin(sy*0.05+1.7)*2.2;     // the coast wanders as it nears
        var bx2=Math.round(ex+curve*(0.35+dp2)), bw2=5+Math.round(dp2*5)+((sy*7)%2); // broad visible beach widens toward the viewer
        g.fillStyle=css(sand); g.fillRect(side>0?bx2:bx2-bw2,sy,bw2,1);      // dry sand
        g.fillStyle=rgba(sand,0.45); g.fillRect(side>0?bx2+bw2:bx2-bw2-2,sy,2,1);   // fades into the grass
        g.fillStyle=css(wet); g.fillRect(side>0?bx2-1:bx2+1-1,sy,1,1);       // wet sand at the waterline
        var lap=Math.sin(now*0.0016+sy*0.55+A);                              // FOAM laps in and out
        if(lap>-0.2){ var fw=1+(lap>0.55?1:0);
          g.fillStyle="rgba(255,255,255,"+(0.24+0.30*Math.max(0,lap)).toFixed(2)+")";
          // The decorative beach meanders inland, but moving foam must remain on the TRUE sea
          // side of the coast. Without this clamp, curved rows flashed over brown dirt/roadbed.
          var foamX=side>0?Math.min(ex-1-fw,bx2-1-fw):Math.max(ex+1,bx2+1);
          g.fillRect(foamX,sy,fw,1); }
        if(((sy*13+((now/900)|0))%11)===0){                                  // an occasional breaker rolling in
          g.fillStyle=day?"rgba(255,255,255,0.5)":"rgba(200,220,255,0.35)";
          var breakX=side>0?Math.min(ex-3,bx2-4):Math.max(ex+1,bx2+2);
          g.fillRect(breakX,sy,2,1); }
      }
      drawShoreLife(g,ex,side,wTop,depth,tideK,L,now,xa,xb);   // what the tide uncovers, and what lives on it
      if(!day&&night>0.3){                                     // the moon lays a glint path on dark water
        var gx2=Math.max(xa+3,Math.min(xb-3,((xa+xb)>>1)+((A>0?-6:6))));
        g.globalCompositeOperation="lighter";
        for(var gy2=wTop+2;gy2<wTop+depth;gy2+=2){ var jig=((Math.sin(gy2*1.3+now*0.002)*2.5)|0);
          var gw2=1+((Math.sin(gy2*0.7+now*0.001)+1)*1.3|0);         // the path breathes wider and narrower
          g.fillStyle="rgba(190,210,245,"+(0.06+0.11*((gy2-wTop)/depth)).toFixed(3)+")";
          g.fillRect(gx2+jig-(gw2>>1),gy2,gw2,1); }
        g.globalCompositeOperation="source-over";
      }
    } }
}

// the settlers' FERRY: until the causeway is paved, the only way across the open water
// is a flat raft poled back and forth — it carries a wagon over, span by span
function drawFerry(g,L,now){
  if(!hasOcean||seaW<=0) return;
  var day=L>0.5, fy=HORIZON+4, bands=[[0,WW*seaW],[WW*(1-seaW),WW]];
  for(var fb=0;fb<bands.length;fb++){ var A=bands[fb][0], B=bands[fb][1];
    var run=Math.max(8,B-A-26), T=34000+fb*9000;
    var ph=((now+fb*13000)/T)%2, f=ph<1?ph:2-ph, fdir=ph<1?1:-1;   // ping-pong shore to shore
    var fwx=A+10+f*run;
    for(var wf=-1;wf<=1;wf++){ var FX=(fwx-WOFF+wf*WW)|0; if(FX<-16||FX>SW+16) continue;
      g.fillStyle=day?"#8a6242":"#4a3a26"; g.fillRect(FX,fy,13,2);            // raft deck
      g.fillStyle=day?"#6a4a30":"#362a1a"; g.fillRect(FX,fy,1,2); g.fillRect(FX+12,fy,1,2);
      g.fillStyle=day?"#5a4028":"#2c2014"; g.fillRect(FX+1,fy-3,1,3); g.fillRect(FX+11,fy-3,1,3);   // rope posts
      g.fillStyle="rgba(120,100,70,0.6)"; g.fillRect(FX+1,fy-3,11,1);         // rope rail
      g.fillStyle=day?"#6a4a30":"#3a2c1c"; g.fillRect(FX+3,fy-2,5,1);         // the wagon aboard
      g.fillStyle=day?"#e8e2d2":"#8a857a"; g.fillRect(FX+4,fy-4,3,2);         // its canvas bonnet
      var pole=(Math.floor(now/400))&1;                                       // the ferryman poling
      drawPerson(g,FX+(fdir>0?10:2),fy-1,day?"#7a5a3a":"#3e3020",SKINC[fb+1],pole);
      g.fillStyle="rgba(120,100,70,0.7)"; g.fillRect(FX+(fdir>0?12:0),fy-4+pole,1,4);
      g.fillStyle=day?"rgba(255,255,255,0.35)":"rgba(150,180,220,0.3)";       // wake trailing behind
      g.fillRect(FX+(fdir>0?-3:14),fy+1,3,1); g.fillRect(FX+(fdir>0?-1:13),fy+2,1,1);
      if(!day){ g.globalCompositeOperation="lighter"; g.fillStyle="rgba(255,200,90,0.35)";   // bow lantern
        g.fillRect(FX+(fdir>0?11:0),fy-5,2,2); g.globalCompositeOperation="source-over"; }
    }
  }
}

// ---- weekend farmers' market: striped stalls + produce + shoppers (residential/oldtown) ----
// A MARKET IS A PLACE, NOT A WALL TEXTURE.
// This used to drop a stall every 15 world px across every residential and oldtown block — and each
// stall is 8 px wide with a stallholder AND a shopper. Eight pixels of stall in every fifteen of
// frontage, tiled unbroken across most of the city, every one the same table under the same striped
// awning. That is the solid wall of bodies in Nick's screenshot, and it is why "the people aren't
// moving" kept surviving every fix: they were not the citizen sim at all, they were two static
// figures stamped into an endlessly repeating tile.
// Now it is a handful of real market ROWS — four to eight stalls together, with open pavement
// between them. Still a pure function of position and the world seed: no state, no new arrays.
function drawMarket(g,L,now){
  var gy=HORIZON+1, ac=["#d23b3b","#2f9a5f","#e0a83a","#3a70b0","#a04a8a"], prod=["#e0402a","#f0a828","#3ac85a","#f07028","#e060c0","#ffd23a"];
  var SITE=260;                                                        // one candidate market per ~260 world px
  for(var si=0; si*SITE<WW; si++){
    var sh=P_hash((si*2654435761 ^ (WORLD_SEED>>>0))>>>0);
    if((sh>>>7)%10 < 3) continue;                                      // not every stretch of the city has one
    var sx0=si*SITE + (sh%150), nSt=4+((sh>>>11)%5);                   // where it sits, and how long the row is
    for(var st=0; st<nSt; st++){
      var mx=sx0+st*13; if(mx>=WW) break;
      var dn=districtAt(mx).name; if(dn!=="residential"&&dn!=="oldtown") continue;
    for(var off=-WW;off<=WW;off+=WW){ var X=(mx-WOFF+off)|0; if(X<-6||X>SW+8) continue;
      var pr=rng((mx*131+7)>>>0), c=ac[(mx>>2)%ac.length];
      g.fillStyle="#8a6a4a"; g.fillRect(X-3,gy-6,1,6); g.fillRect(X+4,gy-6,1,6);           // posts
      for(var aw=0;aw<8;aw++){ g.fillStyle=((aw&1)?c:"#eef1f6"); g.fillRect(X-3+aw,gy-6,1,1); }  // striped awning
      g.fillStyle=L>0.5?"#6a5238":"#241a12"; g.fillRect(X-3,gy-2,8,2);                     // table
      for(var pp=0;pp<6;pp++){ g.fillStyle=prod[(pp+ (mx>>1))%prod.length]; g.fillRect(X-3+pp+((pp>2)?1:0),gy-3,1,1); }  // produce
      drawPerson(g,X+3,gy-2,"#5a7a4a",SKINC[(mx)%SKINC.length],-1);                          // stallholder
      if(pr()<0.75) drawPerson(g,X-4,gy-2,PEDC[(mx>>1)%PEDC.length],SKINC[(mx>>2)%SKINC.length],-1);  // shopper
    }
    }
  }
}
// ---- marathon: a dense stream of numbered runners flowing one way ----
function drawMarathon(g,L,now){
  var vests=["#ff4d4d","#4aa8ff","#ffd23a","#6affc0","#ff7ad0","#eef2ff"];
  for(var k=0;k<Math.round(WW/5);k++){
    var wx=wrapW(k*5 + now*0.03 + (k%3)*1.7), sx=wx-WOFF;
    if(sx>SW+3&&sx-WW>-3) sx-=WW; if(sx<-3&&sx+WW<SW+3) sx+=WW; if(sx<-2||sx>SW+2) continue;
    var lane=k%3, y=HORIZON-1+lane, bob=((sx+((now*0.02)|0)+k)&1);
    drawPerson(g,sx,y,vests[k%vests.length],SKINC[k%SKINC.length],bob);
    g.fillStyle="#ffffff"; g.fillRect(sx|0,(y+1-bob)|0,1,1);                                // race bib
  }
}
// ---- outdoor movie night: a big flickering screen + a seated audience ----
function drawMovie(g,L,now,night){
  var mx=Math.round(0.365*WW);
  for(var off=-WW;off<=WW;off+=WW){ var X=(mx-WOFF+off)|0; if(X<-24||X>SW+8) continue;
    var scW=22, scH=13, scY=HORIZON-18;
    g.fillStyle=L>0.5?"#4a4e58":"#0b0c12"; g.fillRect(X-1,scY-1,scW+2,scH+2);              // frame
    var f=(Math.floor(now/220))%4, mc=[["#3a466a","#8fa0c8"],["#7a4a2a","#f0c088"],["#2a5060","#7ad0e0"],["#5a4460","#c8a0d8"]][f];
    g.fillStyle=mc[0]; g.fillRect(X,scY,scW,scH); g.fillStyle=mc[1]; g.fillRect(X+2+f,scY+2,scW-6,4); g.fillRect(X+4,scY+scH-4,scW-9,2);
    if(night>0.3){ g.globalCompositeOperation="lighter"; g.fillStyle="rgba(150,180,230,0.10)";  // projector glow over the crowd
      g.beginPath(); g.moveTo(X,scY+scH); g.lineTo(X-4,HORIZON); g.lineTo(X+scW+4,HORIZON); g.lineTo(X+scW,scY+scH); g.closePath(); g.fill(); g.globalCompositeOperation="source-over"; }
    g.fillStyle=L>0.5?"#3a3a44":"#14141c"; g.fillRect(X+2,scY+scH,2,3); g.fillRect(X+scW-4,scY+scH,2,3);   // posts
    for(var row=0;row<3;row++) for(var seat=0;seat<9;seat++){                                // audience
      if(((seat*3+row+ (mx))%7)===0) continue;
      drawSeated(g,X+1+seat*2, HORIZON-2-row, PEDC[(seat*3+row)%PEDC.length], SKINC[(seat+row)%SKINC.length]); }
  }
}
// ---- concert: a lit stage at the fairground with light beams, a band, and a dense crowd ----
// the concert now sets up at a REAL venue: the widest standing THEATER in town gets the stage out
// front (marquee glowing behind the band). No theater built yet -> the old fairground pitch.
function concertVenueX(){
  if(!near||!near.blds) return null;
  var theater=null, club=null;
  for(var i=0;i<near.blds.length;i++){ var b=near.blds[i];
    if(b.type==="park") continue;
    if(!buildingStanding(b,cityG)) continue;
    if(overSite(b.x,b.w)||overLandmark(b.x,b.w)) continue;
    if(bldUse(b)==="theater"){ if(!theater||b.w>theater.w) theater=b; }
    else if(b.district==="neon"){ if(!club||b.w>club.w) club=b; }   // no theater built → the biggest club on the strip
  }
  var v=theater||club;
  if(v) return Math.round(v.x+v.w/2);
  if(cityG>0.5 && typeof LM_STADIUM!=='undefined') return Math.round(LM_STADIUM*WW+62);   // stadium show — out front of the big bowl
  return null;
}
function drawConcert(g,L,now,night){
  var vx=concertVenueX(), mx=(vx!=null)?vx:Math.round(0.885*WW), stW=28, stH=9;
  for(var off=-WW;off<=WW;off+=WW){ var X=(mx-WOFF+off)|0; if(X<-50||X>SW+50) continue;
    var sy=HORIZON-stH, x0=X-(stW>>1);
    g.fillStyle=L>0.5?"#241c30":"#0a0712"; g.fillRect(x0,sy-9,stW,9);                       // backdrop screen
    var f=(Math.floor(now/240))%4, sc=[["#3a2f5a","#8f7ad0"],["#5a2f3a","#e08fa0"],["#2f4a5a","#7ad0e0"],["#2f5a3a","#7ae0a0"]][f];
    g.fillStyle=sc[0]; g.fillRect(x0+1,sy-8,stW-2,7); g.fillStyle=sc[1]; g.fillRect(x0+3+f,sy-6,stW-8,3);   // screen visuals
    g.fillStyle=L>0.5?"#2e2636":"#100b18"; g.fillRect(x0,sy,stW,stH);                       // stage deck
    for(var b=0;b<4;b++){ var bx=x0+5+b*6, bob=((Math.floor(now/150)+b)&1); drawPerson(g,bx,sy-1,"#1c1a22",SKINC[(b*3)%SKINC.length],bob); }  // band
    if(night>0.15){ g.globalCompositeOperation="lighter";
      var bc=["rgba(255,60,120,0.10)","rgba(60,150,255,0.10)","rgba(120,255,160,0.10)","rgba(255,200,60,0.10)"];
      for(var lb=0;lb<4;lb++){ var sweep=Math.sin(now*0.0011+lb*1.9)*16; g.fillStyle=bc[lb];
        g.beginPath(); g.moveTo(x0+4+lb*6,sy-9); g.lineTo(X-24+sweep+lb*12,sy-66); g.lineTo(X-14+sweep+lb*12,sy-66); g.closePath(); g.fill(); }
      g.globalCompositeOperation="source-over"; }
    for(var c=0;c<30;c++){ var row=c%2, cxp=x0-16+((c>>1)*5)+(row?2:0)+((c*7)%3), bob=((c*5+(Math.floor(now/170)))&1);   // crowd facing the stage — LOOSE, not a wall (Nick)
      if(cxp<X-62||cxp>X+62) continue; drawPerson(g,cxp,HORIZON-1-row,PEDC[(c*2)%PEDC.length],SKINC[c%SKINC.length],bob); }
  }
}
// ---- food festival: a run of food stalls with striped awnings, string lights, grill smoke, crowds ----
function drawFoodFest(g,L,now,night){
  var gy=HORIZON+1, night2=night>0.28;
  var awn=["#d2683b","#c23b5a","#3a9a6f","#e0a83a","#8a4ab0"], food=["#f0902a","#e0402a","#ffd23a","#8ae05a"];
  // spaced-out booths on market row only — each a CLEAR canopy stall, not a wall of stalls
  for(var mx=26; mx<WW; mx+=24){ var dn=districtAt(mx).name; if(dn!=="residential"&&dn!=="oldtown") continue;
    for(var off=-WW;off<=WW;off+=WW){ var X=(mx-WOFF+off)|0; if(X<-12||X>SW+14) continue;
      var seed=(mx*151+13)>>>0, pr=rng(seed), c=awn[(mx>>2)%awn.length], bw=11, x0=X-(bw>>1);
      g.fillStyle=L>0.5?"#6a4e34":"#241a10"; g.fillRect(x0,gy-9,bw,2);                          // canopy top bar
      for(var aw=0;aw<bw;aw++){ g.fillStyle=((aw&1)?c:"#f4efe4"); g.fillRect(x0+aw,gy-7,1,1); }   // striped valance
      g.fillStyle=L>0.5?"#7a5a3a":"#2a2016"; g.fillRect(x0,gy-7,1,7); g.fillRect(x0+bw-1,gy-7,1,7);  // posts
      g.fillStyle=L>0.5?"#5a4230":"#1c140c"; g.fillRect(x0,gy-3,bw,3);                             // counter
      for(var pp=0;pp<3;pp++){ g.fillStyle=food[(pp+(mx>>1))%food.length]; g.fillRect(x0+2+pp*3,gy-4,2,1); }  // 3 distinct dishes
      g.fillStyle=L>0.5?"#2e2620":"#0e0b08"; g.fillRect(x0-2,gy-6,2,4); g.fillStyle="#f4d38a"; g.fillRect(x0-2,gy-6,2,1);  // menu board on a post
      // ---- LIGHTS: warm booth glow + a bright bulb string across the canopy (visible by day, clearly LIT at night)
      if(night2){ g.globalCompositeOperation="lighter";
        g.fillStyle="rgba(255,178,78,0.26)"; g.fillRect(x0-2,gy-9,bw+4,11);                       // warm pool of light over the whole booth
        g.fillStyle="rgba(255,196,104,0.5)"; g.fillRect(x0,gy-10,bw,4);                           // bulb-string halo along the canopy
        g.fillStyle="rgba(255,208,120,0.6)"; g.fillRect(X-2,gy-7,5,5);                            // lantern halo
        g.globalCompositeOperation="source-over"; }
      g.fillStyle="#ffd86a"; g.fillRect(X,gy-6,1,2);                                             // lantern body (crisp)
      for(var bl=0;bl<4;bl++){ g.fillStyle="#fff0b4"; g.fillRect(x0+1+bl*3,gy-9,1,1); }            // bright bulb string
      drawPerson(g,X+2,gy-3,"#8a5a3a",SKINC[mx%SKINC.length],-1);                                  // vendor
      if(pr()<0.7) drawPerson(g,x0-3,gy-2,PEDC[(mx>>1)%PEDC.length],SKINC[(mx>>2)%SKINC.length],((now*0.02|0)&1));  // one customer
    }
  }
}
// ---- championship parade: the team wins it all — confetti rain, team banners, cheering crowds ----
function drawChampionship(g,L,now){
  var tc=(teamCols&&teamCols[0])||"#d23b3b", tc2=(teamCols&&teamCols[1])||"#f2ede2";
  for(var k=0;k<Math.round(WW/3);k++){                                                       // cheering crowd lining the boulevard
    var wx=wrapW(k*3 + (k%2)*1.5), sx=wx-WOFF; if(sx>SW+3&&sx-WW>-3)sx-=WW; if(sx<-3&&sx+WW<SW+3)sx+=WW; if(sx<-2||sx>SW+2) continue;
    if((k%5)===0) continue; var bob=((k*3+(Math.floor(now/150)))&1);
    drawPerson(g,sx,HORIZON-1,(k&1)?tc:PEDC[k%PEDC.length],SKINC[k%SKINC.length],bob);
  }
  for(var i=0;i<120;i++){                                                                     // confetti rain
    var cx=((i*47+ (now*0.05))% (SW+20))-10, cy=((i*83+ now*0.09)% (HORIZON-6)), cc=[tc,tc2,"#ffd23a","#4aa8ff"][i&3];
    g.fillStyle=cc; g.fillRect(cx|0,cy|0,1,1);
  }
}
// ---- winter ice rink: a pale sheet of ice in the plaza with skaters looping and rink-edge lights ----
function drawIceRink(g,L,now,night){
  var mx=Math.round(0.415*WW), rW=30, rH=8;
  for(var off=-WW;off<=WW;off+=WW){ var X=(mx-WOFF+off)|0; if(X<-40||X>SW+40) continue;
    var rx=X-(rW>>1), ry=HORIZON-1;
    g.fillStyle=L>0.5?"#c8dce6":"#3a4a58"; g.fillRect(rx,ry,rW,rH);                          // ice sheet
    g.fillStyle=L>0.5?"#e8f2f8":"#4a5c6a"; for(var sh=0;sh<5;sh++){ g.fillRect((rx+3+sh*6)|0,(ry+1+((sh+ (now*0.01|0))%3))|0,3,1); }  // ice sheen streaks
    g.fillStyle=L>0.5?"#8a9aa6":"#20303c"; g.fillRect(rx-1,ry-1,1,rH+1); g.fillRect(rx+rW,ry-1,1,rH+1);   // rink rails
    for(var p=0;p<6;p++){ var ph=now*0.0016+p*1.05, sx2=X+Math.cos(ph)*(rW/2-4), sy2=ry+2+Math.sin(ph)*2, bob=((Math.floor(now/160)+p)&1);   // skaters looping on the ice
      drawPerson(g,sx2,sy2,PEDC[(p*2)%PEDC.length],SKINC[p%SKINC.length],bob); }
    if(night>0.3){ g.globalCompositeOperation="lighter"; g.fillStyle="rgba(160,200,240,0.10)"; g.fillRect(rx,ry,rW,rH); g.globalCompositeOperation="source-over";
      for(var lp=0;lp<4;lp++){ g.fillStyle="#ffe08a"; g.fillRect((rx+lp*10)|0,(ry-3)|0,1,3); } }   // rink-edge light poles
  }
}
// ============================ LANDMARKS & ATTRACTIONS ============================
// Prominent fixed structures that appear once the city is established (gated by cityG),
// plus sky attractions (balloons, an ad-blimp). All pure functions of the world clock.
var LM_STADIUM=0.63, LM_CATHEDRAL=0.24, LM_FERRIS=0.93;        // world-x fractions
var LM_CITYHALL=0.415, LM_SCHOOL=0.685, LM_MUSEUM=0.275, LM_COASTER=0.885, LM_MEGA=[0.44,0.565];
var LM_COURTHOUSE=0.468, LM_CAPITOL=0.505, LM_POLICE=0.335, LM_FIRE=0.365, LM_LIBRARY=0.72, LM_POST=0.78;  // government district (courthouse shifted left so the winged capitol has room)
var schoolAt=0.42, EDUB=0, POPK=0.5, SMALLW=false;   // SMALLW: single-monitor world — fewer, tighter landmarks     // per-life school timing; early schooling hastens the space age (N8)
var lmFoot=[];                                                 // cleared plaza footprints (world x-ranges), rebuilt each frame
// THE VILLAGE'S OWN THREE ANCHORS, as fractions of the world. Everything else the metropolis reserves
// — stadium, capitol, courthouse, airport apron, the whole sports complex — is released back to
// housing here, which is the entire reason the village looked empty: those plazas cover most of a
// 2269 wp world, and once the metropolis landmarks were banned they were simply holes.
var VLM_GATES=0.155, VLM_ACADEMY=0.505, VLM_TRAINING=0.815;
// Nick: "add more buildings that would make someone think this is naruto". Four more places, each
// picked because it is a thing you could NAME rather than more village texture: the leader's tower,
// the noodle stand, the walled clan compounds and the shrine path up the hill. World fractions
// chosen to miss every LM_* the restyled civic set already occupies.
// ⚠⚠ THE TOWER WAS STANDING IN FRONT OF THE FACES. Nick: "make sure no building blocks the Stone
// Faces." MEASURED at his geometry: the carved panel is 53.5*FK wide at FK≈5.2, so it occupies world
// 0.204–0.326 — and the leader's tower sat at 0.225, dead inside it, with its cone roof across the
// leftmost elder. It was placed "just left of the rock" back when the rock was a narrow billboard;
// widening the carving to five separated heads swallowed the tower's plot without anything saying so.
// 🔑 A CLEARANCE STATED IN A COMMENT IS NOT A CLEARANCE ENFORCED IN CODE — see `vlmClear()` below,
// which is the enforcement, and is asserted against every one of these fractions at build time.
var VLM_TOWER=0.400, VLM_RAMEN=0.66, VLM_SHRINE=0.955, VLM_CLAN=[0.075,0.755];
// THE ROCK sits behind and just left of the tower, which is where the reference puts it. World-
// anchored like everything else here — see the note in drawBiomeLandmark about the three monuments.
var VLM_ROCK=0.265;
// ⚠⚠ AND ITS SIZE HAS TO BE WORLD-ANCHORED TOO. The carving's scale was `max(KSP*1.6, SW/150)` — SW
// is the SCREEN's width, so at his three monitors (776 · 853 · 640 wp) the same monument was drawn
// 5.17, 5.69 and 4.27 px per unit: a fifth bigger on the middle screen than on the left one, with the
// join between them running down a bezel. The placement bug on this rock was fixed months ago and
// this is the same bug in the other axis — 🔑 A SIZE IS WORLD-ANCHORED ONLY IF WHAT IT IS MEASURED
// AGAINST IS. `WW/438` reproduces the intended scale at his geometry and cannot differ per screen.
function vlmFK(){ return Math.max(Math.max(1,KSP)*1.6, WW/438); }
// THE ONE SOURCE for how wide the face row is. The keep-out and the carving MUST agree — a reserved
// plaza computed from a second copy of this arithmetic is a plaza that stops agreeing the first time
// either copy is touched, which is how the tower ended up standing in the middle of the monument.
function vlmRockSpan(){
  if(!curVillage||curRainV) return null;
  var FK=vlmFK(), fw=Math.round(6.5*FK), pitch=fw+Math.round(3.4*FK);
  var panelW=Math.round(5*pitch+4*FK), cx=Math.round(VLM_ROCK*WW);
  return [cx-Math.round(panelW*0.5)-Math.round(2*FK), cx+Math.round(panelW*0.5)+Math.round(2*FK)];
}
// Nothing the village builds may stand in the face row's span. Asserted here rather than trusted to
// the fractions above being eyeballed apart, because they were eyeballed apart and one of them wasn't.
function vlmClear(f){
  var sp=vlmRockSpan(); if(!sp) return true;
  var x=Math.round(f*WW);
  return x<sp[0]-8 || x>sp[1]+8;
}
// The leader's tower is the ONE piece of village architecture tall enough to reach the face row, so
// it is the one that gets pushed rather than trusted. Computed, not written down: if the carving ever
// grows again, the tower gets out of its way instead of quietly standing in front of it for a month.
function vlmTowerX(){
  if(vlmClear(VLM_TOWER)) return VLM_TOWER;
  var sp=vlmRockSpan();
  return Math.min(0.97,(sp[1]+Math.round(24*vlmFK()))/WW);
}
// THE RAIN VILLAGE's own fractions. The tower sits a third of the way along so it is never on the
// same screen edge as the lock, and both are clear of the pipe bridge's supports.
var RLM_TOWER=0.50, RLM_LOCK=0.86;
function computeLmFoot(){ lmFoot.length=0;
  // 🚨 THE VILLAGE CLEARS ALMOST NOTHING. A plot census said 54 plots should draw and a draw-call
  // recorder said only 7 did; the difference was `overLandmark`, true for nearly every plot on screen.
  // ⚠ AND THE FIRST PROBE MISSED IT — I sampled `overLandmark` BEFORE calling draw(), and `lmFoot` is
  // rebuilt every frame, so it read empty and cleared the mechanism of suspicion. Per-frame state has
  // to be sampled AFTER the frame that builds it.
  if(curVillage){
    var vg=Math.round(VLM_GATES*WW),   va=Math.round(VLM_ACADEMY*WW), vt=Math.round(VLM_TRAINING*WW);
    lmFoot.push([vg-22,vg+22]);        // the great gates
    // ⚠ NO BLANKET RESERVATION IN FRONT OF THE FACES, DELIBERATELY. It is the obvious answer to "no
    // building blocks the Stone Faces" and it is the wrong one here: the span is ~300 of 2269 wp, and
    // over-reserving is exactly what emptied this land the first time — it would clear a bald strip
    // through the middle of the village under the one thing you are meant to be looking at, and the
    // reference has houses packed right up to the cliff. Ordinary houses CANNOT reach the chins; the
    // clearance is enforced where it belongs, in the carving's own seat (see `maxRoofH+23*FK`), and
    // the one thing that could reach — a landmark tower — is pushed out of the span by `vlmTowerX`.
    lmFoot.push([va-26,va+26]);        // the academy tower
    lmFoot.push([vt-30,vt+30]);        // the training ground
    // …and a plaza for each restyled civic compound, sized to the compound rather than to the
    // metropolis building it replaces. ⚠ These MUST be reserved or houses stand inside the council
    // hall — but they must also stay small: over-reserving is exactly what emptied this land before.
    var VC=[[LM_CITYHALL,26],[LM_CAPITOL,29],[LM_COURTHOUSE,20],[LM_CATHEDRAL,18],[LM_LIBRARY,19],
            [LM_POST,16],[LM_MUSEUM,20],[LM_SCHOOL,20],[LM_POLICE,16],[LM_FIRE,16],
            [LM_STADIUM,33],[LM_COASTER,25],[LM_FERRIS,18],[LM_HERO,14]];
    for(var vi=0;vi<VC.length;vi++){
      var vcx=Math.round(VC[vi][0]*WW), vch=VC[vi][1];
      lmFoot.push([vcx-vch,vcx+vch]);
    }
    return;
  }
  // the plots are reserved from the start (fairground), so no buildings get "demolished" when landmarks rise
  var sc=Math.round(LM_STADIUM*WW); lmFoot.push([sc-56,sc+56]);   // MASSIVE stadium needs a wider cleared plaza
  var hc=Math.round(LM_CITYHALL*WW); lmFoot.push([hc-36,hc+36]);   // wide plaza — city hall + annexes grow MONUMENTAL with the city
  var scl=Math.round(LM_SCHOOL*WW); lmFoot.push([scl-12,scl+12]);
  var mu=Math.round(LM_MUSEUM*WW); lmFoot.push([mu-12,mu+12]);
  var mx0=Math.round(LM_MEGA[0]*WW); lmFoot.push([mx0-10,mx0+10]);
  if(heroEra()){ var hh=Math.round(LM_HERO*WW); lmFoot.push([hh-16,hh+16]); }   // clear a plaza for this life's hero monument
  var cth=Math.round(LM_COURTHOUSE*WW); lmFoot.push([cth-26,cth+26]);       // government district (courthouse + capitol always) — grow with maturity
  var cap=Math.round(LM_CAPITOL*WW); lmFoot.push([cap-44,cap+44]);           // the winged capitol commands a broad ceremonial plaza
  if(!SMALLW){                                                  // the big-world extras
    var cc=Math.round(LM_CATHEDRAL*WW); lmFoot.push([cc-15,cc+15]);
    var co=Math.round(LM_COASTER*WW); lmFoot.push([co-44,co+44]);   // wider plaza: the amusement park (ferris wheel + coaster) spans ~80px
    var mx1=Math.round(LM_MEGA[1]*WW); lmFoot.push([mx1-10,mx1+10]);
    var pol=Math.round(LM_POLICE*WW); lmFoot.push([pol-13,pol+13]);         // police + fire (public safety; they grow with the city now)
    var fir=Math.round(LM_FIRE*WW); lmFoot.push([fir-13,fir+13]);
    var lib=Math.round(LM_LIBRARY*WW); lmFoot.push([lib-14,lib+14]);        // library + post office
    var pos=Math.round(LM_POST*WW); lmFoot.push([pos-14,pos+14]); }
  if(cityG>0.55){ lmFoot.push([airportX-52,airportX+58]); }      // clear an APRON around the airport so its runway/terminal read as an airfield, not buried among towers
  if(!NOSPORTS && cityG>0.45){ lmFoot.push([Math.round(SPORTS_X[0]*WW)-56, Math.round(SPORTS_X[3]*WW)+76]); }   // v1.46: reserve the whole SPORTS COMPLEX span → no towers or jumbotrons land on the arenas (NOSPORTS-gated so the containment A/B stays byte-identical)
}
function overLandmark(bx,bw){ for(var i=0;i<lmFoot.length;i++){ if(bx<lmFoot[i][1] && bx+bw>lmFoot[i][0]) return true; } return false; }

