  if(mod===1){ var gi=Math.round(s.gini*100); return [gi>=45?"INEQUALITY WIDENS":"WEALTH WATCH","TOP TIER HOLD "+Math.round(s.richPct*100)+" PCT - GINI "+gi]; }
