        g.fillStyle=rgba([200,26,22],(0.60-0.38*(dq/Math.max(1,Math.round(11*K*bk))))*bk);
        g.fillRect(cx-(dw>>1)+Math.round(Math.sin(dq*0.5)*K*0.6),tfB+Math.round(2.4*K)+dq,dw,1);
