        var profd=Math.pow(1-td,1.42)+Math.max(0,0.10-Math.abs(td-0.42))*0.9;
        dyq=Math.round(HORIZON-_dH*profd)+Math.round(Math.sin(cwx*0.07)*1.6*K*(1-td));
        if(dyq<Math.round(6*K)) dyq=Math.round(6*K);
