    // and sized so a person would fit through it, which is what makes it read as a way in.
    var cvX=dmx+Math.round(dmW*0.13), cvW=Math.max(4,Math.round(dmW*0.042)), cvH=Math.max(4,Math.round(dmH*0.052));
