  if(cityG<0.985) drawTerrain(g,cityG,L,now,nd,(pass==="fg"||pass==="city"||pass==="live")?"fg":undefined);
  drawPlainsWorked(g,L,now,nd);   // the worked prairie, ON the ground the terrain just laid down
